  a = true
  local Y =
    '-- ==========================================================\n--                 AUTO SCIENCE! MAKER\n--   Collects chemicals (Science Station harvest + drops),\n--   goes to the Laboratory, drops the chemicals in, punches\n--   and collects the result. Supports multiple worlds.\n--   Runs until you press STOP.\n-- ==========================================================\n\n-- ModFly is enabled only while this automation is actively running.\n\n-- SETTINGS\nlocal delayf = 75    -- fast pickup step delay (ms)\nlocal delayp = 110   -- fast punch/drop delay (ms)\n\nlocal running = false\nlocal stopRun = false\nlocal currentWorldIndex = 1\n\nlocal dropPos = nil   -- { world = "NAME", x = tileX, y = tileY } set with the SET DROP POSITION button\n\nlocal hudVisible = false\nlocal hud = { mode = "-", status = "Ready", world = "-", count = 0, drop = "not set" }\n\n-- every notify also updates the HUD status line\ndo\n    local _notify = growtopia.notify\n    pcall(function()\n        growtopia.notify = function(msg)\n            hud.status = (tostring(msg):gsub("\\n", " "))\n            return _notify(msg)\n        end\n    end)\nend\n\n-- ==========================================================\n--                         CONFIG\n-- ==========================================================\nlocal SCIENCE_STATION_ID = 928          -- from the Provider script\nlocal LAB_NAME = "Laboratory"\nlocal CHEM_TARGET = 200            -- collect each needed chemical up to this amount before going to the lab\nlocal DROP_THRESHOLD = 200         -- when the result item reaches this, go to the drop position\nlocal LAB_PUNCHES = 2                -- punches on the lab\nlocal LAB_PUNCH_GAP = 1200           -- ms between punches (do not go too fast, or the lab breaks)\n\n-- Recipes (name -> amount). Verify once in the Laboratory\n-- that these amounts match.\nlocal MC_NAME = "Mysterious Chemical"\nlocal MC_RECIPE = { ["Chemical Y"] = 20, ["Chemical B"] = 10, ["Chemical P"] = 5 } -- => makes 1\n\nlocal RECIPES = {\n    -- Forcefield: 1x Mysterious Chemical + 20x Chemical G (wiki)\n    forcefield = { label = "Forcefield", result = "Forcefield", yield = 1,\n        ingredients = { [MC_NAME] = 1, ["Chemical G"] = 20 } },\n    -- Fuelpack: => makes 5\n    fuelpack = { label = "Fuelpack", result = "Fuel Pack", yield = 5,\n        ingredients = { [MC_NAME] = 1, ["Chemical G"] = 10, ["Chemical B"] = 2 } },\n    -- Mystery Chemical => makes 1\n    mystery = { label = "Mystery Chemical", result = "Mysterious Chemical", yield = 1, ingredients = MC_RECIPE },\n}\n\n-- More recipes (Growtopia wiki). Verify once in the Laboratory.\nlocal function chem(c) return "Chemical " .. c end\nRECIPES.intellect   = { label = "Enhanced Intellect", result = "Enhanced Intellect", yield = 1,\n    ingredients = { [MC_NAME] = 3, [chem("B")] = 3, [chem("Y")] = 3 } }\nRECIPES.shockhair   = { label = "Shocking Hair", result = "Shocking Hair", yield = 1,\n    ingredients = { [chem("B")] = 1, [chem("G")] = 30, [chem("R")] = 4 } }\nRECIPES.slime       = { label = "Slime", result = "Slime", yield = 4,\n    ingredients = { [chem("B")] = 4, [chem("G")] = 15, [chem("P")] = 2 } }\nRECIPES.steeltable  = { label = "Steel Table", result = "Steel Table", yield = 5,\n    ingredients = { [chem("B")] = 2, [chem("G")] = 5, [chem("Y")] = 4 } }\nRECIPES.zegoggles   = { label = "Ze Goggles", result = "Ze Goggles", yield = 1,\n    ingredients = { [chem("B")] = 4, [chem("P")] = 3, [chem("R")] = 2 } }\nRECIPES.combover    = { label = "Combover", result = "Combover", yield = 1,\n    ingredients = { [chem("Y")] = 10, [chem("R")] = 5, [chem("G")] = 5 } }\nRECIPES.shockinator = { label = "Shockinator", result = "Shockinator", yield = 1,\n    ingredients = { [chem("G")] = 10, [chem("R")] = 5, [chem("P")] = 1 } }\nRECIPES.labcoat     = { label = "Lab Coat", result = "Lab Coat", yield = 1,\n    ingredients = { [chem("R")] = 20, [chem("P")] = 20, [chem("Y")] = 5 } }\nRECIPES.dragontail  = { label = "Dragon Tail", result = "Dragon Tail", yield = 1,\n    ingredients = { [chem("G")] = 6, [chem("P")] = 2, [chem("Y")] = 3 } }\n\n-- button order + icons\nlocal ORDER = { "forcefield", "fuelpack", "mystery", "intellect", "shockhair", "slime", "steeltable",\n                "zegoggles", "combover", "shockinator", "labcoat", "dragontail" }\nlocal ICON = { forcefield = "", fuelpack = "", mystery = "", intellect = "", shockhair = "",\n               slime = "", steeltable = "", zegoggles = "", combover = "", shockinator = "",\n               labcoat = "", dragontail = "" }\n\n-- short formula text, e.g. "M = 20Y + 10B + 5P -> 1"\nlocal ABBR = { [MC_NAME] = "M", ["Chemical Y"] = "Y", ["Chemical G"] = "G",\n               ["Chemical B"] = "B", ["Chemical P"] = "P", ["Chemical R"] = "R" }\nlocal ABBR_ORDER = { MC_NAME, "Chemical Y", "Chemical G", "Chemical B", "Chemical P", "Chemical R" }\nlocal function formula(key)\n    local r = RECIPES[key]\n    local parts = {}\n    for _, name in ipairs(ABBR_ORDER) do\n        local a = r.ingredients[name]\n        if a then table.insert(parts, a .. ABBR[name]) end\n    end\n    local left = (key == "mystery") and "M" or r.label\n    return left .. " = " .. table.concat(parts, " + ") .. "  ->  " .. (r.yield or 1)\nend\n\n-- ==========================================================\n--                         HELPERS\n-- ==========================================================\nlocal function trim(s)\n    return (tostring(s or ""):match("^%s*(.-)%s*$"))\nend\n\nlocal function parseWorlds(input)\n    local worlds = {}\n    if type(input) ~= "string" then return worlds end\n    for world in input:gmatch("[^,]+") do\n        world = trim(world)\n        if world ~= "" then table.insert(worlds, world:upper()) end\n    end\n    return worlds\nend\n\nlocal function waitForWorld(worldName, timeout)\n    local waited = 0\n    while waited < timeout and not stopRun do\n        if GetWorldName():upper() == worldName:upper() then return true end\n        Sleep(250)\n        waited = waited + 250\n    end\n    return GetWorldName():upper() == worldName:upper()\nend\n\nlocal function isNear(tx, ty)\n    local player = GetLocal()\n    if not player then return false end\n    return math.abs(player.posX / 32 - tx) <= 2 and math.abs(player.posY / 32 - ty) <= 2\nend\n\nlocal function punch(x, y)\n    local player = GetLocal()\n    SendPacketRaw(false, {\n        x = player.posX, y = player.posY,\n        px = x, py = y,\n        type = 3, value = 18\n    })\nend\n\nlocal function count(id)\n    return growtopia.checkInventoryCount(id) or 0\nend\n\nlocal function sortLeftToRight(list)\n    table.sort(list, function(a, b)\n        if a.x == b.x then return a.y < b.y end\n        return a.x < b.x\n    end)\nend\n\n-- names -> IDs, returns nil if a name is not found\nlocal idName = {}  -- item ID -> name (for status messages)\n\nlocal function resolveRecipe(ingredients)\n    local need = {}\n    for name, amount in pairs(ingredients) do\n        local id = growtopia.getItemID(name)\n        if type(id) ~= "number" or id <= 0 then\n            growtopia.notify("Unknown item: " .. name)\n            return nil\n        end\n        need[id] = amount\n        idName[id] = name\n    end\n    return need\nend\n\nlocal function missing(need)\n    local m, any = {}, false\n    for id, amount in pairs(need) do\n        local have = count(id)\n        if have < amount then m[id] = amount - have; any = true end\n    end\n    return m, any\nend\n\n-- Item ID of a world object (field name differs between APIs)\nlocal function objItemId(obj)\n    return tonumber(obj.itemid or obj.id or obj.itemID or obj.itemId or obj.item)\nend\n\nlocal function objPixelPosition(obj)\n    if not obj then return nil, nil end\n    local pos = obj.pos or obj.position\n    local ox = (pos and (pos.x or pos.posX)) or obj.x or obj.posX\n    local oy = (pos and (pos.y or pos.posY)) or obj.y or obj.posY\n    return tonumber(ox), tonumber(oy)\nend\n\n-- Declare before collectDrops so the local function is visible inside it.\nlocal sortRows\n\n-- Picks up drops on the ground (walks over them).\n-- With a filter table {itemID = amount} it ONLY goes for those items,\n-- so it does not wander around the whole world for unrelated drops.\nlocal function collectDrops(filter)\n    Sleep(80)\n    local tiles, seen = {}, {}\n    for _, obj in pairs(GetObjectList()) do\n        if stopRun then return end\n        local id = objItemId(obj)\n        local wanted = (not filter) or (id ~= nil and filter[id])\n        local ox, oy = objPixelPosition(obj)\n        if wanted and ox and oy then\n            local tx, ty = math.floor(ox / 32), math.floor(oy / 32)\n            local key = tx .. \':\' .. ty\n            if not seen[key] then\n                seen[key] = true\n                tiles[#tiles + 1] = { x = tx, y = ty }\n            end\n        end\n    end\n    sortRows(tiles)\n    for _, tile in ipairs(tiles) do\n        if stopRun then return end\n        local before = {}\n        if filter then\n            for id in pairs(filter) do before[id] = count(id) end\n        end\n\n        -- First aim at the exact tile holding the drop. FindPath may stop\n        -- beside an occupied tile, so allow time for pickup before retrying.\n        FindPath(tile.x, tile.y)\n        for _ = 1, 8 do\n            if stopRun then return end\n            Sleep(180)\n            local pickedUp = false\n            if filter then\n                for id in pairs(filter) do\n                    if count(id) > (before[id] or 0) then pickedUp = true; break end\n                end\n            end\n            if pickedUp then break end\n        end\n    end\nend\n-- top to bottom, then left to right (row by row)\nsortRows = function(list)\n    table.sort(list, function(a, b)\n        if a.y == b.y then return a.x < b.x end\n        return a.y < b.y\n    end)\nend\n\n-- Picks up needed drops lying within 2 tiles of (cx, cy), row by row.\nlocal function collectNear(cx, cy, filter)\n    Sleep(60)\n    local list, seen = {}, {}\n    for _, obj in pairs(GetObjectList()) do\n        local ox, oy = objPixelPosition(obj)\n        if ox and oy then\n            local tx, ty = math.floor(ox / 32), math.floor(oy / 32)\n            local id = objItemId(obj)\n            local wanted = (not filter) or (id ~= nil and filter[id])\n            local key = tx .. \':\' .. ty\n            if wanted and math.abs(tx - cx) <= 2 and math.abs(ty - cy) <= 2 and not seen[key] then\n                seen[key] = true\n                list[#list + 1] = { x = tx, y = ty }\n            end\n        end\n    end\n    sortLeftToRight(list)\n    for _, o in ipairs(list) do\n        if stopRun then return end\n        FindPath(o.x, o.y)\n        Sleep(math.max(delayf, 90))\n    end\nend\n-- Forward declaration: gatherInWorld uses this to stop at the required amount.\nlocal canMake\n\n-- Science Collect follows Provider Auto Collect\'s pickup cycle:\n-- scan tracked drops -> walk to drop -> wait delayf -> check pickup range\n-- -> wait delayp -> verify the drop disappeared -> rescan/retry.\n-- The tracked set is restricted to the selected recipe\'s required chemicals.\nlocal function gatherInWorld(filter, harvestStations, recipeKey)\n    local function worldObjects()\n        local objects\n        if type(GetObjects) == "function" then\n            local ok, result = pcall(GetObjects)\n            if ok and type(result) == "table" then objects = result end\n        end\n        if not objects and type(GetObjectList) == "function" then\n            local ok, result = pcall(GetObjectList)\n            if ok and type(result) == "table" then objects = result end\n        end\n        return objects or {}\n    end\n\n    local function dropStillThere(itemID, tileX, tileY)\n        for _, obj in pairs(worldObjects()) do\n            if objItemId(obj) == itemID then\n                local ox, oy = objPixelPosition(obj)\n                if ox and oy and math.floor(ox / 32) == tileX and math.floor(oy / 32) == tileY then\n                    return true\n                end\n            end\n        end\n        return false\n    end\n\n    local function playerNearDrop(tileX, tileY)\n        local player = GetLocal()\n        if not player then return false end\n        local px = player.posX or (player.pos and player.pos.x)\n        local py = player.posY or (player.pos and player.pos.y)\n        if not px or not py then return false end\n        return math.abs(px / 32 - tileX) <= 1 and math.abs(py / 32 - tileY) <= 1\n    end\n\n    local visited, attempts = {}, {}\n    while true do\n        if stopRun then return false end\n        if recipeKey and canMake(recipeKey) then return true end\n\n        local objects = {}\n        for _, obj in pairs(worldObjects()) do\n            if stopRun then return false end\n            local id = objItemId(obj)\n            -- Only recipe chemicals are eligible; ignore every other drop.\n            if id and filter and filter[id] then\n                local ox, oy = objPixelPosition(obj)\n                if ox and oy then\n                    objects[#objects + 1] = { id = id, x = math.floor(ox / 32),\n                        y = math.floor(oy / 32), px = math.floor(ox), py = math.floor(oy) }\n                end\n            end\n        end\n\n        table.sort(objects, function(a, b)\n            if a.y ~= b.y then return a.y < b.y end\n            if a.x ~= b.x then return a.x < b.x end\n            return a.id < b.id\n        end)\n\n        local foundNewTarget = false\n        for _, obj in ipairs(objects) do\n            if stopRun then return false end\n            if recipeKey and canMake(recipeKey) then return true end\n\n            local key = tostring(obj.id) .. ":" .. tostring(obj.px) .. ":" .. tostring(obj.py)\n            if not visited[key] then\n                attempts[key] = (attempts[key] or 0) + 1\n                if attempts[key] >= 3 then visited[key] = true end\n\n                FindPath(obj.x, obj.y)\n                Sleep(delayf)\n                if stopRun then return false end\n\n                -- Provider\'s same proximity-check and pickup wait sequence.\n                if playerNearDrop(obj.x, obj.y) then\n                    Sleep(delayp)\n                    if not dropStillThere(obj.id, obj.x, obj.y) then\n                        visited[key] = true\n                    end\n                end\n\n                foundNewTarget = true\n                if recipeKey and canMake(recipeKey) then return true end\n            end\n        end\n\n        -- Re-scan after each pass so missed drops are retried, just like Provider.\n        if not foundNewTarget then break end\n        Sleep(250)\n    end\n\n    return recipeKey and canMake(recipeKey) or false\nend\n\n-- Sends a text packet (tries different API names)\nlocal function sendText(text)\n    -- Use the same packet API order as the working Provider drop routine.\n    local tries = {\n        function() sendPacket(2, text) end,\n        function() SendPacket(2, text) end,\n        function() growtopia.sendPacket(2, text) end,\n        function() growtopia.SendPacket(2, text) end,\n    }\n    for _, f in ipairs(tries) do\n        if pcall(f) then return true end\n    end\n    return false\nend\n\n-- Drops the requested quantity reliably, one ingredient at a time.\n-- Always open a fresh native drop dialog for each ingredient, then verify\n-- the exact inventory decrease. If that path fails, retry with the API.\nlocal function dropItem(id, amount)\n    local name = idName[id] or tostring(id)\n    local initial = count(id)\n    if initial < amount then\n        growtopia.notify("Not enough " .. name .. " (" .. initial .. "/" .. amount .. ")")\n        return false\n    end\n\n    local remaining = amount\n    local noProgress = 0\n    while remaining > 0 and noProgress < 4 do\n        if stopRun then return false end\n        local before = count(id)\n        if before <= 0 then break end\n        local requested = math.min(remaining, before)\n        local changed = false\n\n        -- Clear a previous item\'s popup so the next chemical cannot be skipped.\n        pcall(function()\n            sendText("action|dialog_return\\ndialog_name|drop_item\\nbuttonClicked|cancel")\n        end)\n        Sleep(250)\n\n        -- Native dialog route: open the selected item\'s dialog and submit\n        -- this exact item ID and quantity.\n        if type(growtopia.dropItem) == "function" then\n            pcall(function() growtopia.dropItem(id) end)\n            Sleep(450)\n            pcall(function()\n                sendText("action|dialog_return\\ndialog_name|drop_item\\nitemID|" .. id .. "\\ncount|" .. requested .. "\\nbuttonClicked|drop")\n            end)\n            for i = 1, 32 do\n                Sleep(250)\n                local after = count(id)\n                if after < before then\n                    local dropped = math.min(before - after, remaining)\n                    remaining = remaining - dropped\n                    changed = true\n                    break\n                end\n            end\n        end\n\n        -- API fallback, only if the native dialog did not change inventory.\n        if not changed and remaining > 0 and type(growtopia.confirmDropItem) == "function" then\n            local apiBefore = count(id)\n            pcall(function() growtopia.confirmDropItem(id, requested) end)\n            for i = 1, 32 do\n                Sleep(250)\n                local after = count(id)\n                if after < apiBefore then\n                    local dropped = math.min(apiBefore - after, remaining)\n                    remaining = remaining - dropped\n                    changed = true\n                    break\n                end\n            end\n        end\n\n        if changed then\n            noProgress = 0\n            pcall(function()\n                sendText("action|dialog_return\\ndialog_name|drop_item\\nbuttonClicked|cancel")\n            end)\n            Sleep(1100)\n        else\n            noProgress = noProgress + 1\n            pcall(function()\n                sendText("action|dialog_return\\ndialog_name|drop_item\\nbuttonClicked|cancel")\n            end)\n            Sleep(900)\n        end\n    end\n\n    if remaining <= 0 then\n        growtopia.notify("Dropped " .. name .. " x" .. amount)\n        Sleep(700)\n        return true\n    end\n\n    growtopia.notify("Drop incomplete: " .. name .. " (" .. (amount - remaining) .. "/" .. amount .. ")")\n    return false\nend\n\n-- ==========================================================\n--                  2) LABORATORY (COMBINE)\n-- ==========================================================\nlocal function findLab()\n    local labID = growtopia.getItemID(LAB_NAME)\n    if type(labID) ~= "number" or labID <= 0 then return nil end\n    local best, bestD = nil, math.huge\n    local p = GetLocal()\n    local px, py = p.posX / 32, p.posY / 32\n    for _, tile in pairs(GetTiles()) do\n        if tile.fg == labID then\n            local d = math.abs(tile.x - px) + math.abs(tile.y - py)\n            if d < bestD then best, bestD = tile, d end\n        end\n    end\n    return best\nend\n\n-- Walks ONTO the lab (picks up what lies there). If the lab is solid,\n-- stands on the tile directly above it instead.\nlocal function stepOnLab(lab)\n    FindPath(lab.x, lab.y)\n    Sleep(delayf + 300)\n\n    local p = GetLocal()\n    local onLab = p and math.abs(p.posX / 32 - lab.x) < 1 and math.abs(p.posY / 32 - lab.y) < 1\n    if not onLab then\n        FindPath(lab.x, lab.y - 1)\n        Sleep(delayf + 300)\n    end\n    Sleep(500) -- let the pickup happen\nend\n\n-- k = how many batches to put in at once (bulk). Returns ok, producedCount.\nlocal function combine(need, resultName, k)\n    k = k or 1\n    local lab = findLab()\n    if not lab then\n        growtopia.notify("Laboratory not found in this world.")\n        return false\n    end\n\n    -- result item (for verification)\n    local resultID = resultName and growtopia.getItemID(resultName)\n    if type(resultID) ~= "number" or resultID <= 0 then resultID = nil end\n    local resultBefore = resultID and count(resultID) or 0\n\n    -- walk next to the lab so that we FACE it (drops land in front of us):\n    -- stand 2 tiles away, then step 1 tile toward the lab\n    local approaches = {\n        { {lab.x - 2, lab.y}, {lab.x - 1, lab.y} },  -- from the left, facing right\n        { {lab.x + 2, lab.y}, {lab.x + 1, lab.y} },  -- from the right, facing left\n    }\n    local arrived = false\n    for _, ap in ipairs(approaches) do\n        FindPath(ap[1][1], ap[1][2])\n        Sleep(delayf + 150)\n        FindPath(ap[2][1], ap[2][2])\n        Sleep(delayf + 250)\n        if isNear(lab.x, lab.y) then arrived = true break end\n    end\n    if not arrived then\n        growtopia.notify("Could not reach the Laboratory.")\n        return false\n    end\n\n    -- 1) DROP EVERY ingredient required by this recipe (verified).\n    -- Build an ordered list instead of relying on pairs(), so all recipe\n    -- ingredients are handled predictably and none are silently skipped.\n    local ingredients = {}\n    for id, amount in pairs(need) do\n        ingredients[#ingredients + 1] = { id = id, amount = amount }\n    end\n    table.sort(ingredients, function(a, b)\n        local an = tostring(idName[a.id] or a.id)\n        local bn = tostring(idName[b.id] or b.id)\n        return an < bn\n    end)\n\n    for index, ingredient in ipairs(ingredients) do\n        if stopRun then return false end\n        local id, amount = ingredient.id, ingredient.amount * k\n        local have = count(id)\n        local name = idName[id] or ("Chemical/item " .. tostring(id))\n        if have < amount then\n            growtopia.notify("Missing recipe ingredient " .. index .. "/" .. #ingredients .. ": " .. name .. " (" .. have .. "/" .. amount .. ").")\n            stepOnLab(lab)\n            return false\n        end\n        growtopia.notify("Lab drop " .. index .. "/" .. #ingredients .. ": " .. name .. " x" .. amount)\n        if not dropItem(id, amount) then\n            -- Pick up any ingredients already dropped and stop; never punch\n            -- the Laboratory with an incomplete recipe.\n            stepOnLab(lab)\n            return false\n        end\n        -- Confirm this exact ingredient left the inventory before moving on.\n        local left = count(id)\n        if left > have - amount then\n            growtopia.notify("Ingredient drop not fully confirmed: " .. name .. ". Stopping before Lab punch.")\n            stepOnLab(lab)\n            return false\n        end\n        Sleep(350)\n    end\n    Sleep(delayp + 300)\n\n    -- 2) PUNCH (slowly, so it does not break)\n    for i = 1, LAB_PUNCHES do\n        if stopRun then return false end\n        if not GetTile(lab.x, lab.y) or GetTile(lab.x, lab.y).fg ~= lab.fg then\n            growtopia.notify("Laboratory disappeared! Stopping.")\n            return false\n        end\n        punch(lab.x, lab.y)\n        Sleep(LAB_PUNCH_GAP)\n    end\n    Sleep(600)\n\n    -- 3) STEP ONTO the lab and pick up what it made (nothing else)\n    stepOnLab(lab)\n\n    -- verify that the result arrived\n    if resultID and count(resultID) <= resultBefore then\n        growtopia.notify("Combine gave no result. Stopping (check the recipe/drop).")\n        return false\n    end\n    local produced = resultID and (count(resultID) - resultBefore) or 0\n    return true, produced\nend\n\n-- ==========================================================\n--                           UI\n-- ==========================================================\nlocal ui = UserInterface.new("ZS AUTO SCIENCE!", "Science")\n\nui:addLabelApp("* ZS AUTO SCIENCE! *", "Science")\nui:addTooltip(\n    "* AUTO SCIENCE! *",\n    "Welcome, scientist! \\n" ..\n    "Forcefield - Fuelpack - Mystery Chemical - and more\\n" ..\n    "Creator: ZadStay\\n\\n" ..\n    "QUICK START\\n" ..\n    "1. Enter the Collect worlds (Science Stations).\\n" ..\n    "2. Enter the Lab world (with the Laboratory).\\n" ..\n    "3. Choose what to make and press the button.\\n\\n" ..\n    "The script collects chemicals, goes to the Lab\\n" ..\n    "world, drops them into the Laboratory and\\n" ..\n    "collects the result. Repeats until STOP.\\n\\n" ..\n    "DROP POSITION: stand where you want the items\\n" ..\n    "dropped and press SET DROP POSITION. At 200 of\\n" ..\n    "the made item it drops them there by itself.\\n\\n" ..\n    "Use STOP to pause safely. Your place is saved.\\n\\n" ..\n    "Happy science! ",\n    "Info",\n    true\n)\nui:addDivider()\n\nZS_label(ui, "1. WORLDS")\nui:addInputString("Collect", "", "Collect worlds", "", "World", "sci_world_list")\nui:addInputString("Lab", "", "Lab world", "", "World", "sci_lab_world")\n\nui:addDivider()\nZS_label(ui, "2. SETTINGS")\nui:addSlider("Delay", 50, 1000, 190, 10, false, "sci_delay")\nui:addButton("SET DROP POSITION", "sci_setdrop")\n\nui:addDivider()\nZS_label(ui, "3. SELECT ITEMS")\nfor _, key in ipairs(ORDER) do\n    ui:addToggle(ICON[key] .. " " .. RECIPES[key].label, false, "sci_select_" .. key, true)\n    ZS_label(ui, formula(key))\nend\nui:addDivider()\nui:addToggle("> AUTO SCIENCE - START / STOP", false, "sci_run", true)\n\naddIntoModule(ui:generateJSON(), "ZS")\n\n-- Pink floating status box removed. Status is shown through game notifications.\n\n-- ==========================================================\n--                         MAIN RUN\n-- ==========================================================\n-- Targets to collect: one recipe batch of only the raw chemicals needed\n-- by the selected item (including Mysterious Chemical base ingredients).\nlocal function buildTargets(recipe)\n    -- Calculate only the raw chemicals required for ONE batch of this\n    -- selected recipe. Once this minimum is collected, labPhase uses every\n    -- available matching ingredient in inventory to craft in bulk.\n    -- If the recipe needs Mysterious Chemical, include its base ingredients\n    -- in the correct recipe ratio instead of collecting unrelated chemicals.\n    local requiredPerBatch = {}\n\n    local function addRaw(name, amount)\n        requiredPerBatch[name] = (requiredPerBatch[name] or 0) + amount\n    end\n\n    for name, amount in pairs(recipe.ingredients) do\n        if name == MC_NAME and recipe.ingredients ~= MC_RECIPE then\n            for cname, cAmount in pairs(MC_RECIPE) do\n                addRaw(cname, cAmount * amount)\n            end\n        else\n            addRaw(name, amount)\n        end\n    end\n\n    local targets = {}\n    for name, amount in pairs(requiredPerBatch) do\n        local id = growtopia.getItemID(name)\n        if type(id) ~= "number" or id <= 0 then\n            growtopia.notify("Unknown item: " .. name)\n            return nil\n        end\n        idName[id] = name\n        targets[id] = amount\n    end\n    return targets\nend\n\n-- how many full batches of `need` the inventory allows\nlocal function batches(need)\n    local k = math.huge\n    for id, amt in pairs(need) do\n        k = math.min(k, math.floor(count(id) / amt))\n    end\n    if k == math.huge then k = 0 end\n    return k\nend\n\n-- limit batches so no single ingredient drop exceeds one stack (200)\nlocal function capBatches(need, k)\n    for _, amt in pairs(need) do\n        k = math.min(k, math.floor(200 / amt))\n    end\n    return k\nend\n\n-- can we make at least one batch (crafting Mysterious Chemical first if needed)?\ncanMake = function(key)\n    local recipe = RECIPES[key]\n    local mainNeed = resolveRecipe(recipe.ingredients)\n    if not mainNeed then return false end\n    local mcAmount = recipe.ingredients[MC_NAME]\n    if not mcAmount then return batches(mainNeed) >= 1 end\n\n    local mcId = growtopia.getItemID(MC_NAME)\n    local mcBase = resolveRecipe(MC_RECIPE)\n    local others = {}\n    for id, a in pairs(mainNeed) do if id ~= mcId then others[id] = a end end\n    if batches(others) < 1 then return false end\n    return count(mcId) >= mcAmount or batches(mcBase) >= 1\nend\n\nlocal function warpTo(world)\n    hud.world = world\n    if GetWorldName():upper() == world then return true end\n    growtopia.warpTo(world)\n    if not waitForWorld(world, 15000) then return false end\n    Sleep(700)\n    return true\nend\n\n-- When the made item reaches DROP_THRESHOLD (or force), go to the saved drop\n-- position and drop them there. Returns false if it could not (or no position is set).\nlocal function depositIfFull(recipe, labWorld, force)\n    local resultID = growtopia.getItemID(recipe.result)\n    if type(resultID) ~= "number" or resultID <= 0 then return true end\n    if not force and count(resultID) < DROP_THRESHOLD then return true end\n    if count(resultID) <= 0 then return true end\n\n    idName[resultID] = recipe.result\n\n    if not dropPos then\n        growtopia.notify(recipe.label .. " reached " .. DROP_THRESHOLD .. "! Press SET DROP POSITION. Stopping.")\n        return false\n    end\n\n    growtopia.notify("Full stack! Going to the drop position...")\n    if not warpTo(dropPos.world) then return false end\n    FindPath(dropPos.x, dropPos.y)\n    Sleep(delayf + 400)\n\n    local ok = dropItem(resultID, math.min(count(resultID), DROP_THRESHOLD))\n    Sleep(600)\n\n    if not warpTo(labWorld) then return false end\n    return ok\nend\n\n-- Makes items in BULK: drops many batches into the lab at once, punches once,\n-- repeats until the inventory cannot make another batch.\n-- If the recipe needs Mysterious Chemical it crafts that first (also in bulk).\n-- Returns "done", "stop", "halt" or "nochem".\nlocal function labPhase(key, labWorld)\n    local recipe = RECIPES[key]\n    local yield = recipe.yield or 1\n    local mainNeed = resolveRecipe(recipe.ingredients)\n    if not mainNeed then return "fail" end\n\n    local resultID = growtopia.getItemID(recipe.result)\n    if type(resultID) ~= "number" or resultID <= 0 then\n        growtopia.notify("Unknown item: " .. recipe.result)\n        return "fail"\n    end\n\n    local mcAmount = recipe.ingredients[MC_NAME]\n    local mcId = mcAmount and growtopia.getItemID(MC_NAME)\n    local mcBase = mcAmount and resolveRecipe(MC_RECIPE)\n    local others\n    if mcAmount then\n        others = {}\n        for id, a in pairs(mainNeed) do if id ~= mcId then others[id] = a end end\n    end\n\n    local made = 0\n    while not stopRun do\n        -- result stack (nearly) full => go to the drop position first\n        local room = math.floor((DROP_THRESHOLD - count(resultID)) / yield)\n        if room < 1 then\n            if not depositIfFull(recipe, labWorld, true) then\n                return stopRun and "stop" or "halt"\n            end\n            room = math.floor((DROP_THRESHOLD - count(resultID)) / yield)\n            if room < 1 then return "halt" end\n        end\n\n        local progressed = false\n\n        -- Mysterious Chemical first (bulk), if the recipe uses it\n        if mcAmount then\n            local kOthers = capBatches(others, batches(others))\n            local deficit = kOthers * mcAmount - count(mcId)\n            if deficit > 0 then\n                local kMC = math.min(deficit, batches(mcBase))\n                kMC = capBatches(mcBase, kMC)\n                kMC = math.min(kMC, DROP_THRESHOLD - count(mcId))\n                if kMC >= 1 then\n                    growtopia.notify("Combine: " .. MC_NAME .. " x" .. kMC)\n                    if not combine(mcBase, MC_NAME, kMC) then\n                        return stopRun and "stop" or "halt"\n                    end\n                    progressed = true\n                end\n            end\n        end\n\n        if not progressed then\n            local k = capBatches(mainNeed, batches(mainNeed))\n            k = math.min(k, room)\n            if k < 1 then break end\n\n            growtopia.notify("Combine: " .. recipe.label .. " x" .. (k * yield))\n            local ok, produced = combine(mainNeed, recipe.result, k)\n            if not ok then return stopRun and "stop" or "halt" end\n            made = made + (produced or 0)\n            hud.count = hud.count + (produced or 0)\n        end\n        Sleep(400)\n    end\n\n    if stopRun then return "stop" end\n    return made > 0 and "done" or "nochem"\nend\n\n-- Scan configured collect worlds for ONLY the selected recipe\'s raw chemicals.\n-- As soon as enough ingredients are available, warp to the lab and craft in bulk.\n-- After crafting, return to scanning only if more ingredients are needed.\n-- Returns: "done", "stop", "nochem", "fail", "halt"\nlocal function totalRaw(raw)\n    local t = 0\n    for id in pairs(raw) do t = t + count(id) end\n    return t\nend\n\nlocal function cycle(key)\n    local recipe = RECIPES[key]\n    local raw = buildTargets(recipe)\n    if not raw then return "fail" end\n\n    local worlds = parseWorlds(getValue(2, "sci_world_list"))\n    if #worlds == 0 then worlds = { GetWorldName():upper() } end\n    local labWorld = parseWorlds(getValue(2, "sci_lab_world"))[1] or GetWorldName():upper()\n\n    local madeAny = false\n    local emptyRounds = 0\n\n    -- Repeat the world list when necessary. This matters when the recipe\'s\n    -- ingredients are spread across several worlds: after crafting, revisit\n    -- earlier worlds and look ONLY for the remaining required chemicals.\n    for round = 1, 100 do\n        if stopRun then return "stop" end\n        local collectedThisRound = false\n\n        -- If inventory already contains a complete recipe, go straight to the lab.\n        if canMake(key) then\n            growtopia.notify("Recipe chemicals ready. Going to Laboratory...")\n            if not warpTo(labWorld) then return "fail" end\n            local r = labPhase(key, labWorld)\n            if r == "stop" then return "stop" end\n            if r == "halt" or r == "fail" then return r end\n            if r == "done" then madeAny = true end\n        end\n\n        for wi, world in ipairs(worlds) do\n            if stopRun then return "stop" end\n            currentWorldIndex = wi\n\n            if not warpTo(world) then\n                growtopia.notify("Could not enter: " .. world)\n            else\n                local before = totalRaw(raw)\n                growtopia.notify("Scanning " .. world .. " for required chemicals...")\n                gatherInWorld(raw, true, key)\n                if stopRun then return "stop" end\n\n                if totalRaw(raw) > before then\n                    collectedThisRound = true\n                end\n\n                -- Go to the lab immediately once at least one full batch\n                -- can be made from the selected recipe\'s ingredients.\n                if canMake(key) then\n                    growtopia.notify("Required chemicals collected. Going to Laboratory...")\n                    if not warpTo(labWorld) then return "fail" end\n                    local r = labPhase(key, labWorld)\n                    if r == "stop" then return "stop" end\n                    if r == "halt" or r == "fail" then return r end\n                    if r == "done" then madeAny = true end\n                end\n            end\n        end\n\n        -- A station can be on cooldown or its drop can appear slightly late.\n        -- Retry the complete world list a few times before declaring resources\n        -- exhausted; any successful pickup resets the empty-scan counter.\n        if collectedThisRound then\n            emptyRounds = 0\n        else\n            emptyRounds = emptyRounds + 1\n            if emptyRounds >= 3 then break end\n            growtopia.notify("No new chemicals yet. Re-scanning worlds (" .. emptyRounds .. "/3)...")\n            Sleep(1400)\n        end\n    end\n\n    if stopRun then return "stop" end\n    return madeAny and "done" or "nochem"\nend\n\n-- Complete the selected recipe using only its required chemicals.\n-- Re-scan configured worlds only when another bulk batch needs ingredients.\nlocal function run(key)\n    local d = getValue(1, "sci_delay")\n    if type(d) == "number" and d >= 50 then\n        delayp = d\n        delayf = math.max(40, d)\n    end\n\n    local label = RECIPES[key].label\n    growtopia.notify(label .. " started.")\n\n    local result = cycle(key)\n    if result == "done" then\n        growtopia.notify(label .. " finished. All available chemicals processed. Total made: " .. hud.count)\n    elseif result == "nochem" then\n        growtopia.notify(label .. ": no complete recipe chemicals available in the selected worlds.")\n    elseif result == "halt" then\n        growtopia.notify(label .. " stopped: Laboratory combine failed. Check the lab/drop.")\n    elseif result == "fail" then\n        growtopia.notify(label .. " stopped: could not complete the laboratory cycle.")\n    elseif result == "stop" then\n        growtopia.notify(label .. " stopped by user.")\n    end\nend\n\n-- ==========================================================\n--                        UI EVENTS\n-- ==========================================================\nlocal selectedRecipes = {}\n\nlocal function startSelected()\n    if running then\n        growtopia.notify("Auto Science is already running.")\n        return\n    end\n\n    local queue = {}\n    for _, key in ipairs(ORDER) do\n        if selectedRecipes[key] then table.insert(queue, key) end\n    end\n    if #queue == 0 then\n        growtopia.notify("Select at least one item toggle first.")\n        return\n    end\n\n    running = true\n    stopRun = false\n    pcall(EditToggle, "ModFly", true)\n    hud.count = 0\n    growtopia.notify("Auto Science started for " .. #queue .. " selected item(s).")\n\n    ZS_thread(function()\n        for _, key in ipairs(queue) do\n            if stopRun then break end\n            run(key)\n        end\n        running = false\n        pcall(EditToggle, "ModFly", false)\n        currentWorldIndex = 1\n        if stopRun then\n            growtopia.notify("Auto Science stopped.")\n        else\n            growtopia.notify("All selected items completed.")\n        end\n    end)\nend\n\naddHook(function(evType, name, value)\n    if type(name) == "string" and name:sub(1, 11) == "sci_select_" then\n        local key = name:sub(12)\n        if RECIPES[key] then\n            selectedRecipes[key] = value and true or false\n            growtopia.notify(RECIPES[key].label .. (selectedRecipes[key] and " selected." or " deselected."))\n        end\n    elseif name == "sci_run" then\n        if value then\n            startSelected()\n        else\n            stopRun = true\n            growtopia.notify("Auto Science stop requested.")\n        end\n    elseif name == "sci_setdrop" then\n        local p = GetLocal()\n        if p then\n            dropPos = { world = GetWorldName():upper(), x = math.floor(p.posX / 32), y = math.floor(p.posY / 32) }\n            hud.drop = dropPos.world .. " (" .. dropPos.x .. ", " .. dropPos.y .. ")"\n            growtopia.notify("Drop position set: " .. hud.drop)\n        end\n    end\nend, "onValue")\n\ngrowtopia.notify("* Welcome to Auto SCIENCE! *\\nCreator: ZadStay")\n\n'
  local K =
    '-- ==========================================================\n--                 MULTIWORLD PROVIDER V2\n--                     Creator: ZadStay\n-- ==========================================================\n\n-- ModFly is enabled only while this automation is actively running.\n\n-- SETTINGS\nlocal delayf = 250\nlocal delayp = 190\nlocal maxhits = 1\nlocal INVENTORY_STORE_LIMIT = 200\nlocal DISPLAY_BOX_CAPACITY = 4000\n\nlocal farming = false\nlocal collecting = false\nlocal autoCollectEnabled = false\nlocal stopFarming = false\nlocal progressVisible = false\nlocal progressState = {\n    worldIndex = 0, worldTotal = 0, worldName = "Waiting",\n    targetIndex = 0, targetTotal = 0,\n    worldPercent = 0, overallPercent = 0, status = "Ready"\n}\nlocal savedSciencePositions = {}\nlocal savedTacklePositions = {}\nlocal savedOtherPositions = {}\n\n-- RESUME SYSTEM\nlocal currentWorldIndex = 1\nlocal currentTargetIndex = 1\n\n-- PROVIDER IDS\nlocal providerIDs = {\n    science = 928,\n    atm = 1008,\n    tackle = 3044,\n    chicken = 872,\n    cow = 866,\n    sheep = 3888,\n    coffee = 1632,\n    tea = 5116\n}\n\nlocal selectedProviders = {\n    science = false,\n    atm = false,\n    tackle = false,\n    chicken = false,\n    cow = false,\n    sheep = false,\n    coffee = false,\n    tea = false\n}\n\n-- Basic Science Station chemicals\nlocal chemicalIDs = {914, 916, 918, 920, 924}\nlocal chemicalFallbackIDs = {\n    ["Chemical G"] = 914, ["Chemical Y"] = 916, ["Chemical B"] = 918,\n    ["Chemical R"] = 920, ["Chemical P"] = 924\n}\n\n-- Tackle Box output: resolve IDs by item name so the script does not\n-- depend on hard-coded IDs for bait items.\n-- Output item IDs for the non-Science providers. The name lookup is tried\n-- first (so updated item databases win); numeric IDs are reliable fallbacks.\nlocal otherDropNames = {"Egg", "Milk", "Wool", "Coffee", "Tea"}\nlocal otherFallbackIDs = {\n    Egg = 874,       -- Chicken\n    Milk = 868,      -- Cow\n    Wool = 3890,     -- Sheep\n    Coffee = 1634,   -- Coffee Maker\n    Tea = 5118       -- Tea Set\n}\nlocal otherByProvider = {\n    { "chicken", "Egg" }, { "cow", "Milk" }, { "sheep", "Wool" },\n    { "coffee", "Coffee" }, { "tea", "Tea" }\n}\n\n-- Resolve names safely across PowerKuy builds. Some builds return a numeric\n-- string rather than a number; accept both and fall back to the item table.\nlocal function resolveProviderItemID(itemName, fallbackID)\n    if growtopia and type(growtopia.getItemID) == "function" then\n        local ok, resolved = pcall(growtopia.getItemID, itemName)\n        resolved = ok and tonumber(resolved) or nil\n        if resolved and resolved > 0 then return resolved end\n    end\n    return tonumber(fallbackID)\nend\n\nlocal function getOtherIDs()\n    local ids, seen = {}, {}\n    for _, pair in ipairs(otherByProvider) do\n        if selectedProviders[pair[1]] then\n            local itemName = pair[2]\n            local id = resolveProviderItemID(itemName, otherFallbackIDs[itemName])\n            if id and id > 0 and not seen[id] then\n                seen[id] = true\n                table.insert(ids, id)\n            end\n        end\n    end\n    return ids\nend\n\n-- All seven standard Tackle Box drops, including numeric fallbacks.\n-- Item IDs: Wiggly Worm 2914, Shiny Flashy Thing 3012, Salmon Eggs 3014,\n-- Fishing Fly 3016, Shrimp Lure 3018, Uranium Glowing Lure 5526,\n-- Mega-Pellet Bait 5528.\nlocal tackleBaits = {\n    {"Wiggly Worm", 2914},\n    {"Shiny Flashy Thing", 3012},\n    {"Salmon Eggs", 3014},\n    {"Fishing Fly", 3016},\n    {"Shrimp Lure", 3018},\n    {"Mega-Pellet Bait", 5528},\n    {"Uranium Glowing Lure", 5526}\n}\n\n-- Resolve chemicals by NAME (hard-coded IDs are only a fallback).\nlocal chemicalNames = {"Chemical G", "Chemical Y", "Chemical B", "Chemical R", "Chemical P"}\nlocal resolvedChemicals = nil\nlocal function getChemicalIDs()\n    if not selectedProviders.science then return {} end\n    if not resolvedChemicals then\n        local ids, seen = {}, {}\n        for _, n in ipairs(chemicalNames) do\n            local id = nil\n            if growtopia and type(growtopia.getItemID) == "function" then\n                local ok, resolved = pcall(growtopia.getItemID, n)\n                if ok and type(resolved) == "number" and resolved > 0 then id = resolved end\n            end\n            -- Use the known per-chemical fallback even if only some names resolve.\n            id = id or chemicalFallbackIDs[n]\n            if type(id) == "number" and id > 0 and not seen[id] then\n                seen[id] = true\n                table.insert(ids, id)\n            end\n        end\n        resolvedChemicals = ids\n    end\n    return resolvedChemicals\nend\n\nlocal function getTackleIDs()\n    local ids, seen = {}, {}\n    if not selectedProviders.tackle then return ids end\n    for _, bait in ipairs(tackleBaits) do\n        local itemName, fallbackID = bait[1], bait[2]\n        local id = resolveProviderItemID(itemName, fallbackID)\n        if id and id > 0 and not seen[id] then\n            seen[id] = true\n            table.insert(ids, id)\n        end\n    end\n    return ids\nend\n\nlocal function getStorageIDs(kind)\n    if kind == "science" then return getChemicalIDs() end\n    if kind == "tackle" then return getTackleIDs() end\n    if kind == "other" then return getOtherIDs() end\n    return {}\nend\n\nlocal function getStoragePositions(kind)\n    if kind == "science" then return savedSciencePositions end\n    if kind == "tackle" then return savedTacklePositions end\n    if kind == "other" then return savedOtherPositions end\n    return {}\nend\n\n-- Forward declarations\nlocal collectDrops\nlocal autoStore\n\n-- ==========================================================\n--                         PARSERS\n-- ==========================================================\n\nlocal function parseWorlds(input)\n    local worlds = {}\n    if type(input) ~= "string" then return worlds end\n\n    for world in input:gmatch("[^,]+") do\n        world = world:match("^%s*(.-)%s*$")\n        if world ~= "" then\n            table.insert(worlds, world:upper())\n        end\n    end\n    return worlds\nend\n\n\nlocal function getTrackedItemIDs()\n    local ids, seen = {}, {}\n\n    local function addID(id)\n        if type(id) == "number" and id > 0 and not seen[id] then\n            seen[id] = true\n            table.insert(ids, id)\n        end\n    end\n\n    for _, id in ipairs(getChemicalIDs()) do addID(id) end\n    for _, id in ipairs(getTackleIDs()) do addID(id) end\n    for _, id in ipairs(getOtherIDs()) do addID(id) end\n    return ids\nend\n\nlocal function storageItemCount(kind)\n    local total = 0\n    local ids = kind and getStorageIDs(kind) or getTrackedItemIDs()\n    for _, id in ipairs(ids) do total = total + (growtopia.checkInventoryCount(id) or 0) end\n    return total\nend\n\nlocal function anyChemicalStackAtLimit()\n    for _, id in ipairs(getChemicalIDs()) do\n        if (growtopia.checkInventoryCount(id) or 0) >= INVENTORY_STORE_LIMIT then return true end\n    end\n    return false\nend\n\nlocal function anyTackleStackAtLimit()\n    for _, id in ipairs(getTackleIDs()) do\n        if (growtopia.checkInventoryCount(id) or 0) >= INVENTORY_STORE_LIMIT then return true end\n    end\n    return false\nend\n\nlocal function anyOtherStackAtLimit()\n    for _, id in ipairs(getOtherIDs()) do\n        if (growtopia.checkInventoryCount(id) or 0) >= INVENTORY_STORE_LIMIT then return true end\n    end\n    return false\nend\n\nlocal function isTrackedDrop(id, trackedSet)\n    if trackedSet then\n        return trackedSet[id] == true\n    end\n    for _, trackedID in ipairs(getTrackedItemIDs()) do\n        if id == trackedID then return true end\n    end\n    return false\nend\n\nlocal function waitForWorld(worldName, timeout)\n    local waited = 0\n    while waited < timeout and not stopFarming do\n        if GetWorldName():upper() == worldName:upper() then\n            return true\n        end\n        Sleep(250)\n        waited = waited + 250\n    end\n    return GetWorldName():upper() == worldName:upper()\nend\n\n-- ==========================================================\n--                            UI\n-- ==========================================================\n\nlocal ui = UserInterface.new("ZS MULTIWORLD PROVIDER V2", "Agriculture")\n\nui:addLabelApp("* ZS MULTIWORLD PROVIDER V2 *", "Agriculture")\nui:addTooltip("* MULTIWORLD PROVIDER V2 *", "Choose farm worlds, storage worlds and providers.\\nTurn AUTO FARM and AUTO COLLECT ON/OFF as needed.\\nYour progress is saved when you turn AUTO FARM off.", "Info", true)\nui:addDivider()\n\nZS_label(ui, "1. FARM WORLDS")\nui:addInputString(\n    "Worlds to farm",\n    "",\n    "World list",\n    "",\n    "World",\n    "world_list"\n)\n\nui:addDivider()\nZS_label(ui, "2. STORAGE WORLDS & DROP POSITIONS")\nZS_label(ui, "SCIENCE STATION - Chemical storage")\nui:addInputString("Science storage world", "", "Science storage world", "World for Science Station Chemicals", "World", "science_storage_world")\nui:addButton("SET SCIENCE DROP POSITION", "provider_set_science_position")\nui:addDivider()\nZS_label(ui, "TACKLE BOX - Bait storage")\nui:addInputString("Tackle storage world", "", "Tackle storage world", "World for Tackle Box bait", "World", "tackle_storage_world")\nui:addButton("SET TACKLE DROP POSITION", "provider_set_tackle_position")\nui:addDivider()\nZS_label(ui, "FARM PROVIDERS - Egg, Milk, Wool, Coffee & Tea storage")\nui:addInputString("Other provider storage world", "", "Other provider storage world", "World for Chicken, Cow, Sheep, Coffee Maker and Tea Set drops", "World", "other_storage_world")\nui:addButton("SET OTHER PROVIDER DROP POSITION", "provider_set_other_position")\n\nui:addDivider()\nZS_label(ui, "3. SELECT WHAT TO FARM")\nui:addToggle("Science Station", false, "provider_science", true)\nui:addToggle("ATM Machine", false, "provider_atm", true)\nui:addToggle("Tackle Box", false, "provider_tackle", true)\nui:addToggle("Chicken", false, "provider_chicken", true)\nui:addToggle("Cow", false, "provider_cow", true)\nui:addToggle("Sheep", false, "provider_sheep", true)\nui:addToggle("Coffee Maker", false, "provider_coffee", true)\nui:addToggle("Tea Set", false, "provider_tea", true)\n\nui:addDivider()\nZS_label(ui, "4. FARM CONTROLS")\nui:addToggle("> AUTO FARM", false, "provider_run", true)\nui:addToggle("AUTO COLLECT DROPS", false, "provider_collect", true)\n\nlocal json = ui:generateJSON()\naddIntoModule(json, "ZS")\n\n-- ==========================================================\n--                       MOVEMENT / FARM\n-- ==========================================================\n\nlocal function punch(x, y)\n    local player = GetLocal()\n    SendPacketRaw(false, {\n        x = player.posX,\n        y = player.posY,\n        px = x,\n        py = y,\n        type = 3,\n        value = 18\n    })\nend\n\nlocal function isNear(tx, ty)\n    local player = GetLocal()\n    local dx = math.abs(player.posX / 32 - tx)\n    local dy = math.abs(player.posY / 32 - ty)\n    return dx <= 2 and dy <= 2\nend\n\n-- Collection: the player must be standing on the drop tile (1 tile),\n-- tighter than harvesting which allows 2 tiles.\nlocal function isCollectNear(tx, ty)\n    local player = GetLocal()\n    if not player then return false end\n    local dx = math.abs(player.posX / 32 - tx)\n    local dy = math.abs(player.posY / 32 - ty)\n    return dx <= 0.6 and dy <= 0.6\nend\n\n-- Close the native drop dialog for whichever Chemical type (G, Y, R, B, or P) is currently being handled.\n-- Use real newline characters (\\n), not the literal backslash+n sequence.\nlocal function cancelDropDialog()\n    local txt = "action|dialog_return\\ndialog_name|drop_item\\nbuttonClicked|cancel"\n    if not pcall(function() sendPacket(2, txt) end) then\n        pcall(function() SendPacket(2, txt) end)\n    end\n    Sleep(100)\nend\n\n\n-- PowerKuy API documents confirmDropItem(itemID, amount). If a launcher build\n-- errors or does not execute it, fall back to the native drop dialog.\nlocal function performDrop(itemID, amount)\n    local before = growtopia.checkInventoryCount(itemID) or 0\n    if before <= 0 or amount <= 0 then return true end\n    if amount > before then amount = before end\n\n    if type(growtopia.confirmDropItem) == "function" then\n        pcall(function() growtopia.confirmDropItem(itemID, amount) end)\n        Sleep(1100)\n        if (growtopia.checkInventoryCount(itemID) or 0) < before then return true end\n    end\n\n    local opened = pcall(function() growtopia.dropItem(itemID) end)\n    if not opened then return false, "PowerKuy drop API unavailable" end\n    Sleep(300)\n    local submitted = pcall(function()\n        sendPacket(2,\n            "action|dialog_return\\n" ..\n            "dialog_name|drop_item\\n" ..\n            "itemID|" .. itemID .. "\\n" ..\n            "count|" .. amount .. "\\n" ..\n            "buttonClicked|drop"\n        )\n    end)\n    if not submitted then\n        cancelDropDialog()\n        return false, "Could not submit native drop dialog"\n    end\n    Sleep(1100)\n    local after = growtopia.checkInventoryCount(itemID) or 0\n    if after < before then return true end\n    return false, "Inventory count did not change"\nend\n\n-- ==========================================================\n--                AUTO DROP TO DISPLAY BOXES\n-- ==========================================================\n\nautoStore = function(kind, fromCollect)\n    local ids = getStorageIDs(kind)\n    local positions = getStoragePositions(kind)\n    if storageItemCount(kind) <= 0 then return true end\n\n    local storageKey = kind == "science" and "science_storage_world" or (kind == "tackle" and "tackle_storage_world" or "other_storage_world")\n    local storageWorld = getValue(2, storageKey)\n    if type(storageWorld) ~= "string" or storageWorld:match("^%s*$") then\n        growtopia.notify((kind == "science" and "Science" or (kind == "tackle" and "Tackle" or "Other provider")) .. " storage world is missing.")\n        return false\n    end\n    if #positions == 0 then\n        growtopia.notify("No " .. kind .. " drop positions saved. Set a position in front of its Display Box.")\n        return false\n    end\n\n    local returnWorld = GetWorldName()\n    local storageName = storageWorld:match("^%s*(.-)%s*$"):upper()\n    if returnWorld:upper() ~= storageName then\n        growtopia.warpTo(storageName)\n        if not waitForWorld(storageName, 15000) then\n            growtopia.notify("Could not enter " .. storageName .. ". " .. kind .. " items were not dropped.")\n            return false\n        end\n    end\n\n    local storedTotal = 0\n    for _, point in ipairs(positions) do\n        if stopFarming or (fromCollect and not autoCollectEnabled) or storageItemCount(kind) <= 0 then break end\n\n        -- Approach from behind, then return to the saved tile to restore facing.\n        local approachX = point.x + (point.faceLeft and 1 or -1)\n        FindPath(approachX, point.y)\n        Sleep(350)\n        FindPath(point.x, point.y)\n\n        local reached = false\n        for attempt = 1, 60 do\n            Sleep(250)\n            local player = GetLocal()\n            if player and player.posX and player.posY then\n                if math.floor(player.posX / 32) == point.x and math.floor(player.posY / 32) == point.y then\n                    reached = true\n                    break\n                end\n            end\n        end\n\n        if reached then\n            for _, itemID in ipairs(ids) do\n                if stopFarming or (fromCollect and not autoCollectEnabled) then break end\n                local amount = growtopia.checkInventoryCount(itemID) or 0\n                if amount > 0 then\n                    local ok, err = performDrop(itemID, amount)\n                    if ok then\n                        local after = growtopia.checkInventoryCount(itemID) or 0\n                        storedTotal = storedTotal + math.max(0, amount - after)\n                    else\n                        growtopia.notify("Drop failed for item ID " .. itemID .. ": " .. tostring(err))\n                    end\n                end\n            end\n        else\n            growtopia.notify("Could not reach " .. kind .. " drop position " .. point.x .. "," .. point.y .. ". Trying next.")\n        end\n    end\n\n    if fromCollect and not autoCollectEnabled then cancelDropDialog() end\n    local left = storageItemCount(kind)\n    if returnWorld:upper() ~= storageName then\n        growtopia.warpTo(returnWorld)\n        waitForWorld(returnWorld, 15000)\n    end\n    if left == 0 then\n        growtopia.notify((kind == "science" and "Science Chemicals" or (kind == "tackle" and "Tackle bait" or "Farm provider drops")) .. " stored (" .. storedTotal .. " items).")\n        return true\n    end\n    growtopia.notify("Could not drop " .. left .. " " .. kind .. " items. Check box position, access and capacity.")\n    return false\nend\n\n-- ==========================================================\n--                    AUTO COLLECT CHEMICALS\n-- ==========================================================\n\n-- PowerKuy builds expose world drops through either GetObjects() or\n-- GetObjectList(). Prefer the API used by the working standalone farm snippet.\nlocal function getProviderWorldObjects()\n    local objects = nil\n    if type(GetObjects) == "function" then\n        local ok, result = pcall(GetObjects)\n        if ok and type(result) == "table" then objects = result end\n    end\n    if not objects and type(GetObjectList) == "function" then\n        local ok, result = pcall(GetObjectList)\n        if ok and type(result) == "table" then objects = result end\n    end\n    return objects or {}\nend\n\nlocal function objectItemID(o)\n    if not o then return nil end\n    return tonumber(o.itemid or o.itemID or o.id or o.item_id)\nend\n\nlocal function objectPixelPosition(o)\n    if not o then return nil, nil end\n    local pos = o.pos or o.position\n    local ox = (pos and (pos.x or pos.posX)) or o.x or o.posX\n    local oy = (pos and (pos.y or pos.posY)) or o.y or o.posY\n    return tonumber(ox), tonumber(oy)\nend\n\n-- True while a tracked drop of this item is still lying on this tile.\nlocal function dropStillThere(itemID, tileX, tileY)\n    for _, o in pairs(getProviderWorldObjects()) do\n        if o and objectItemID(o) == itemID then\n            local ox, oy = objectPixelPosition(o)\n            if ox and oy and math.floor(ox / 32) == tileX and math.floor(oy / 32) == tileY then\n                return true\n            end\n        end\n    end\n    return false\nend\n\ncollectDrops = function(stopWithFarm, storeAfterCollect)\n    if collecting then return false end\n\n    collecting = true\n    Sleep(300)\n\n    local collectedTargets = 0\n    local skippedDisplayBoxDrops = 0\n    local displayBoxID = nil\n    if growtopia and type(growtopia.getItemID) == "function" then\n        local ok, resolved = pcall(growtopia.getItemID, "Display Box")\n        if ok and type(resolved) == "number" and resolved > 0 then displayBoxID = resolved end\n    end\n\n    -- Resolve the tracked IDs only once. Repeated getItemID calls for every\n    -- world object can overload some launcher builds and freeze/crash the client.\n    local trackedSet = {}\n    for _, trackedID in ipairs(getTrackedItemIDs()) do\n        trackedSet[trackedID] = true\n    end\n\n    -- If the inventory was already full when collection starts, store first.\n    if anyChemicalStackAtLimit() then\n        growtopia.notify("Chemical inventory full. Storing before collecting more.")\n        if not autoStore("science", true) then\n            collecting = false\n            return false\n        end\n    end\n    if anyTackleStackAtLimit() then\n        growtopia.notify("Tackle bait inventory full. Storing before collecting more.")\n        if not autoStore("tackle", true) then collecting = false; return false end\n    end\n    if anyOtherStackAtLimit() then\n        growtopia.notify("Farm provider inventory full. Storing before collecting more.")\n        if not autoStore("other", true) then collecting = false; return false end\n    end\n\n    -- Re-scan the object list after each pass so newly revealed drops\n    -- and every chemical type in chemicalIDs can be collected.\n    local visited = {}\n    local attempts = {}\n\n    while true do\n        if not autoCollectEnabled or (stopWithFarm and stopFarming) then\n            collecting = false\n            return false\n        end\n\n        local rawObjects = getProviderWorldObjects()\n        local objects = {}\n\n        for _, obj in pairs(rawObjects) do\n            local objID = objectItemID(obj)\n            if obj and isTrackedDrop(objID, trackedSet) then\n                local ox, oy = objectPixelPosition(obj)\n                if ox and oy then\n                    table.insert(objects, obj)\n                end\n            end\n        end\n\n        table.sort(objects, function(a, b)\n            local ax, ay = objectPixelPosition(a)\n            local bx, by = objectPixelPosition(b)\n\n            local atx, btx = math.floor(ax / 32), math.floor(bx / 32)\n            local aty, bty = math.floor(ay / 32), math.floor(by / 32)\n\n            -- row by row: top -> bottom, left -> right\n            if aty ~= bty then return aty < bty end\n            if atx ~= btx then return atx < btx end\n            return (objectItemID(a) or 0) < (objectItemID(b) or 0)\n        end)\n\n        local foundNewTarget = false\n\n        for _, obj in ipairs(objects) do\n            if not autoCollectEnabled or (stopWithFarm and stopFarming) then\n                collecting = false\n                return false\n            end\n\n            local objID = objectItemID(obj)\n            if obj and isTrackedDrop(objID, trackedSet) then\n                local ox, oy = objectPixelPosition(obj)\n\n                if ox and oy then\n                    local tileX = math.floor(ox / 32)\n                    local tileY = math.floor(oy / 32)\n                    local objectKey = tostring(objID) .. ":" ..\n                        tostring(math.floor(ox)) .. ":" .. tostring(math.floor(oy))\n\n                    -- Do not collect objects sitting on/in a Display Box tile.\n                    -- Those belong to the box and must remain untouched.\n                    local tile = GetTile(tileX, tileY)\n                    if displayBoxID and tile and tile.fg == displayBoxID then\n                        skippedDisplayBoxDrops = skippedDisplayBoxDrops + 1\n                    elseif not visited[objectKey] then\n                        -- Same rhythm as harvesting: walk -> delayf -> check range -> delayp.\n                        -- Harvest stops up to 2 tiles away; collect walks onto the drop (1 tile).\n                        attempts[objectKey] = (attempts[objectKey] or 0) + 1\n                        if attempts[objectKey] >= 3 then visited[objectKey] = true end\n\n                        FindPath(tileX, tileY)\n                        Sleep(delayf)\n                        if not autoCollectEnabled or (stopWithFarm and stopFarming) then\n                            collecting = false\n                            return false\n                        end\n\n                        if isCollectNear(tileX, tileY) then\n                            Sleep(delayp)\n                            if not dropStillThere(objID, tileX, tileY) then\n                                visited[objectKey] = true\n                                collectedTargets = collectedTargets + 1\n                            end\n                        end\n                        -- Anything left over is retried on the next scan (max 3 tries),\n                        -- so no drop is skipped.\n                        foundNewTarget = true\n\n                        -- Trigger storage immediately as soon as any single Chemical stack reaches 200.\n                        if anyChemicalStackAtLimit() then\n                            growtopia.notify(\n                                "One Chemical type reached 200. Storing tracked items at the saved drop positions now."\n                            )\n                            if not autoStore("science", true) then\n                                collecting = false\n                                return false\n                            end\n                            -- Objects may have changed while we were in the storage world.\n                            visited = {}\n                            attempts = {}\n                        end\n\n                        if anyTackleStackAtLimit() then\n                            growtopia.notify("One Tackle bait stack reached 200. Storing bait separately.")\n                            if not autoStore("tackle", true) then collecting = false; return false end\n                            visited = {}\n                            attempts = {}\n                        end\n                        if anyOtherStackAtLimit() then\n                            growtopia.notify("A farm provider drop stack reached 200. Storing separately.")\n                            if not autoStore("other", true) then collecting = false; return false end\n                            visited = {}\n                            attempts = {}\n                        end\n                    end\n                end\n            end\n        end\n\n        -- Stop when a fresh scan finds no unvisited chemical drops.\n        if not foundNewTarget then break end\n        Sleep(250)\n    end\n\n    collecting = false\n\n    -- Manual Collect All also stores any remainder below the normal\n    -- 200-chemical auto-storage trigger.\n    if storeAfterCollect and autoCollectEnabled then\n        local scienceOK = storageItemCount("science") == 0 or autoStore("science", true)\n        local tackleOK = storageItemCount("tackle") == 0 or autoStore("tackle", true)\n        local otherOK = storageItemCount("other") == 0 or autoStore("other", true)\n        return scienceOK and tackleOK and otherOK\n    end\n\n    return true\nend\n\n-- ==========================================================\n--                    FARM CURRENT WORLD\n-- ==========================================================\n\nlocal function showFarmProgress(worldIndex, worldTotal, worldName, targetIndex, targetTotal, status)\n    local worldPercent = 0\n    if targetTotal > 0 then\n        worldPercent = math.floor((math.max(0, targetIndex - 1) / targetTotal) * 100)\n    elseif targetIndex > 0 then\n        worldPercent = 100\n    end\n\n    local overallPercent = 0\n    if worldTotal > 0 then\n        overallPercent = math.floor(((math.max(0, worldIndex - 1) + (worldPercent / 100)) / worldTotal) * 100)\n    end\n\n    progressState.worldIndex = worldIndex or 0\n    progressState.worldTotal = worldTotal or 0\n    progressState.worldName = tostring(worldName or "Unknown")\n    progressState.targetIndex = math.min(targetIndex or 0, targetTotal or 0)\n    progressState.targetTotal = targetTotal or 0\n    progressState.worldPercent = worldPercent\n    progressState.overallPercent = overallPercent\n    progressState.status = tostring(status or "Working")\nend\n\n-- Simple top-center status bar (no progress bars). Hook provided by Growlauncher.\naddHook(function(deltaTime)\n    if not progressVisible then return end\n    if not ImGui or type(ImVec2) ~= "function" then return end\n\n    pcall(function()\n        local io = ImGui.GetIO()\n        local display = io and io.DisplaySize\n        local screenWidth = display and display.x or 800\n        ImGui.SetNextWindowPos(ImVec2(screenWidth * 0.5, 18), 1, ImVec2(0.5, 0))\n        ImGui.SetNextWindowSize(ImVec2(300, 0), 1)\n        ImGui.SetNextWindowBgAlpha(0.85)\n\n        local visible = ImGui.Begin("##MultiworldProviderHUD")\n        if visible then\n            ImGui.Text("* MULTIWORLD PROVIDER V2 *")\n            ImGui.Text("Creator: ZadStay")\n            ImGui.Separator()\n            ImGui.Text(progressState.status .. "  -  " .. progressState.worldName)\n            ImGui.Text("World " .. tostring(progressState.worldIndex) .. "/" .. tostring(progressState.worldTotal)\n                .. "   Providers " .. tostring(progressState.targetIndex) .. "/" .. tostring(progressState.targetTotal))\n        end\n        ImGui.End()\n    end)\nend, "onDrawImGui")\n\nlocal function farmWorld()\n    local activeIDs = {}\n    if selectedProviders.science then activeIDs[providerIDs.science] = true end\n    if selectedProviders.atm then activeIDs[providerIDs.atm] = true end\n    if selectedProviders.tackle then activeIDs[providerIDs.tackle] = true end\n    if selectedProviders.chicken then activeIDs[providerIDs.chicken] = true end\n    if selectedProviders.cow then activeIDs[providerIDs.cow] = true end\n    if selectedProviders.sheep then activeIDs[providerIDs.sheep] = true end\n    if selectedProviders.coffee then activeIDs[providerIDs.coffee] = true end\n    if selectedProviders.tea then activeIDs[providerIDs.tea] = true end\n\n    local worldTotal = #parseWorlds(getValue(2, "world_list"))\n    local completed, totalTargets = 0, 0\n\n    local function providerRows()\n        local rows, seen = {}, {}\n        local tiles = GetTiles() or {}\n        for _, tile in pairs(tiles) do\n            if tile and tile.x ~= nil and tile.y ~= nil then\n                local current = GetTile(tile.x, tile.y)\n                local fg = current and (current.fg or current.foreground) or tile.fg\n                if activeIDs[fg] then\n                    local y = math.floor(tile.y)\n                    if not seen[y] then\n                        seen[y] = true\n                        rows[#rows + 1] = y\n                    end\n                end\n            end\n        end\n        table.sort(rows)\n        return rows\n    end\n\n    local function providersInRow(rowY)\n        local list = {}\n        local tiles = GetTiles() or {}\n        for _, tile in pairs(tiles) do\n            if tile and tile.x ~= nil and tile.y ~= nil and math.floor(tile.y) == rowY then\n                local current = GetTile(tile.x, tile.y)\n                local fg = current and (current.fg or current.foreground) or tile.fg\n                if activeIDs[fg] then\n                    list[#list + 1] = {x = math.floor(tile.x), y = rowY}\n                end\n            end\n        end\n        table.sort(list, function(a, b) return a.x < b.x end)\n        return list\n    end\n\n    -- Harvest-style row processing:\n    -- hit each ready provider once, move across the row, then rescan that same\n    -- row and return to anything still present before advancing to the next row.\n    while not stopFarming do\n        local rows = providerRows()\n        if #rows == 0 then break end\n\n        local didWorkThisWorld = false\n        for _, rowY in ipairs(rows) do\n            if stopFarming then return false end\n\n            local stalledPasses = 0\n            while not stopFarming do\n                local remaining = providersInRow(rowY)\n                if #remaining == 0 then break end\n\n                local first = remaining[1]\n                if not isNear(first.x, first.y) then\n                    FindPath(first.x + 1, first.y)\n                    Sleep(delayf)\n                end\n\n                local passCleared = false\n                for _, tile in ipairs(remaining) do\n                    if stopFarming then return false end\n\n                    local current = GetTile(tile.x, tile.y)\n                    local fg = current and (current.fg or current.foreground)\n                    if current and activeIDs[fg] then\n                        if not isNear(tile.x, tile.y) then\n                            FindPath(tile.x + 1, tile.y)\n                            Sleep(delayf)\n                        end\n\n                        if isNear(tile.x, tile.y) then\n                            -- One hit only, just like Auto Harvest.\n                            punch(tile.x, tile.y)\n                            Sleep(math.max(100, delayp))\n\n                            local after = GetTile(tile.x, tile.y)\n                            local afterFg = after and (after.fg or after.foreground)\n                            if not after or not activeIDs[afterFg] then\n                                completed = completed + 1\n                                didWorkThisWorld = true\n                                passCleared = true\n                                if autoCollectEnabled and not stopFarming then\n                                    local collectionOK = collectDrops(true, false)\n                                    if not collectionOK or stopFarming then return false end\n                                end\n                            end\n                        end\n                    end\n                end\n\n                -- Verify the whole row again. Any provider missed on the first\n                -- pass is revisited before the script is allowed onto the next row.\n                local afterRow = providersInRow(rowY)\n                if #afterRow == 0 then break end\n\n                if passCleared then\n                    stalledPasses = 0\n                else\n                    stalledPasses = stalledPasses + 1\n                end\n\n                if stalledPasses >= 3 then\n                    growtopia.notify("NO MISS paused: providers remain on row "\n                        .. tostring(rowY) .. ". The row was not skipped.")\n                    return false\n                end\n\n                if not isNear(afterRow[1].x, afterRow[1].y) then\n                    FindPath(afterRow[1].x + 1, afterRow[1].y)\n                    Sleep(delayf)\n                end\n            end\n        end\n\n        if not didWorkThisWorld then\n            growtopia.notify("AUTO FIND paused: no provider was cleared. Check reachability and try again.")\n            return false\n        end\n        Sleep(150)\n    end\n\n    if stopFarming then return false end\n    currentTargetIndex = 1\n    if autoCollectEnabled then\n        return collectDrops(true)\n    end\n    return true\nend\n\n-- ==========================================================\n--                         MULTIWORLD\n-- ==========================================================\n\nlocal function startFarming()\n    stopFarming = false\n\n    local worldInput = getValue(2, "world_list")\n    local worlds = parseWorlds(worldInput)\n\n    if #worlds == 0 then\n        farming = false\n        pcall(EditToggle, "ModFly", false)\n        growtopia.notify("World List is empty.")\n        return\n    end\n\n    if not selectedProviders.science\n    and not selectedProviders.atm\n    and not selectedProviders.tackle\n    and not selectedProviders.chicken\n    and not selectedProviders.cow\n    and not selectedProviders.sheep\n    and not selectedProviders.coffee\n    and not selectedProviders.tea then\n        farming = false\n        pcall(EditToggle, "ModFly", false)\n        growtopia.notify("Select at least one provider.")\n        return\n    end\n\n    if currentWorldIndex > #worlds then\n        currentWorldIndex = 1\n        currentTargetIndex = 1\n    end\n\n    growtopia.notify("Loaded " .. #worlds .. " farm worlds.")\n\n    while currentWorldIndex <= #worlds do\n        if stopFarming then break end\n\n        local world = worlds[currentWorldIndex]\n        showFarmProgress(currentWorldIndex, #worlds, world, 0, 0, "Entering world")\n\n        if GetWorldName():upper() ~= world then\n            growtopia.warpTo(world)\n            if not waitForWorld(world, 15000) then\n                growtopia.notify("Could not enter " .. world .. ". Skipping.")\n                currentWorldIndex = currentWorldIndex + 1\n                currentTargetIndex = 1\n            end\n        end\n\n        if not stopFarming and GetWorldName():upper() == world then\n            growtopia.notify("Farming " .. world)\n\n            local completed = farmWorld()\n            if not completed then break end\n\n            Sleep(700)\n            currentWorldIndex = currentWorldIndex + 1\n            currentTargetIndex = 1\n        end\n    end\n\n    -- Flush any remaining chemicals at the end of the world list.\n    if not stopFarming and currentWorldIndex > #worlds then\n        if storageItemCount("science") > 0 then autoStore("science", false) end\n        if storageItemCount("tackle") > 0 then autoStore("tackle", false) end\n        if storageItemCount("other") > 0 then autoStore("other", false) end\n    end\n\n    farming = false\n    pcall(EditToggle, "ModFly", false)\n\n    if currentWorldIndex > #worlds then\n        showFarmProgress(#worlds, #worlds, GetWorldName(), 1, 1, "Finished")\n        growtopia.notify("MULTIWORLD FARMING FINISHED.")\n        currentWorldIndex = 1\n        currentTargetIndex = 1\n    elseif stopFarming then\n        growtopia.notify("Farming stopped. Position saved.")\n    else\n        growtopia.notify("Farming paused. Position saved.")\n    end\n\n    stopFarming = false\nend\n\n-- ==========================================================\n--                          UI EVENTS\n-- ==========================================================\n\naddHook(function(type, name, value)\n    if name == "provider_science" then\n        selectedProviders.science = value\n    elseif name == "provider_atm" then\n        selectedProviders.atm = value\n    elseif name == "provider_tackle" then\n        selectedProviders.tackle = value\n    elseif name == "provider_chicken" then selectedProviders.chicken = value\n    elseif name == "provider_cow" then selectedProviders.cow = value\n    elseif name == "provider_sheep" then selectedProviders.sheep = value\n    elseif name == "provider_coffee" then selectedProviders.coffee = value\n    elseif name == "provider_tea" then selectedProviders.tea = value\n\n    elseif name == "provider_set_science_position" or name == "provider_set_tackle_position" or name == "provider_set_other_position" then\n        local player = GetLocal()\n        if player and player.posX and player.posY then\n            local x = math.floor(player.posX / 32)\n            local y = math.floor(player.posY / 32)\n            local positions = name == "provider_set_science_position" and savedSciencePositions or (name == "provider_set_tackle_position" and savedTacklePositions or savedOtherPositions)\n            local duplicate = false\n            for _, point in ipairs(positions) do\n                if point.x == x and point.y == y then duplicate = true break end\n            end\n            if duplicate then\n                growtopia.notify("Position already saved: " .. x .. "," .. y)\n            else\n                table.insert(positions, {x = x, y = y, faceLeft = player.isLeft and true or false})\n                local kind = name == "provider_set_science_position" and "SCIENCE" or (name == "provider_set_tackle_position" and "TACKLE" or "OTHER PROVIDER")\n                growtopia.notify("Saved " .. kind .. " position " .. x .. "," .. y .. ". Face its Display Box before saving.")\n            end\n        else\n            growtopia.notify("Could not read your current position.")\n        end\n\n    elseif name == "provider_collect" then\n        autoCollectEnabled = value and true or false\n        if autoCollectEnabled then\n            growtopia.notify("AUTO COLLECT: ON. Drops will be collected left to right.")\n            if not farming and not collecting then\n                stopFarming = false\n                ZS_thread(function()\n                    collectDrops(false, true)\n                end)\n            end\n        else\n            cancelDropDialog()\n            growtopia.notify("AUTO COLLECT: OFF. Collection stopped and any open drop dialog was cancelled.")\n        end\n\n    elseif name == "provider_run" and value then\n        if farming then return end\n\n        farming = true\n        stopFarming = false\n        pcall(EditToggle, "ModFly", true)\n        progressVisible = true\n        progressState.status = "Starting"\n        progressState.worldName = "Preparing worlds"\n        progressState.worldIndex = 0\n        progressState.worldTotal = 0\n        progressState.targetIndex = 0\n        progressState.targetTotal = 0\n        progressState.worldPercent = 0\n        progressState.overallPercent = 0\n        growtopia.notify("Multiworld Provider V2 started.")\n\n        ZS_thread(function()\n            startFarming()\n        end)\n\n    elseif name == "provider_run" and not value then\n        stopFarming = true\n        growtopia.notify("AUTO FARM: OFF. Saving current position.")\n    end\nend, "onValue")\n\ngrowtopia.notify("* Welcome to Multiworld Provider V2 *\\nCreator: ZadStay")\n\n'
  local w =
    '-- ==========================================================\n-- ZS AUTO SURGERY V2 - Growlauncher 7.0.1+\n-- Automatic tool selection + optional helpers.\n-- Features that require an undocumented game-side interaction\n-- are exposed as manual helpers rather than guessed packets.\n-- ==========================================================\nlocal TOOL = {\n    Sponge=1258, Scalpel=1260, Anesthetic=1262, Antibiotic=1266,\n    Splint=1268, Stitches=1270, FixIt=1296, Pins=4308,\n    Transfusion=4310, Defibrillator=4312, Clamp=4314, Ultrasound=4316,\n    LabKit=4318\n}\nlocal RULES = {\n    {"Anesthetic", "`4The patient wakes up!"},\n    {"Anesthetic", "`4The patient screams and flails!"},\n    {"Defibrillator", "Status: `4Heart stopped!"},\n    {"Anesthetic", "Status: `6Coming to"},\n    {"Transfusion", "Pulse: `4"},\n    {"Antibiotic", "Temp: `4%d"}, {"LabKit", "Temp: `4%d"},\n    {"Antibiotic", "Temp: `6%d"}, {"LabKit", "Temp: `6%d"},\n    {"Antibiotic", "Temp: `3%d"}, {"LabKit", "Temp: `3%d"},\n    {"Clamp", "Patient is losing blood `4very quickly!"},\n    {"Stitches", "Patient is losing blood `4very quickly!"},\n    {"Clamp", "Patient is `6losing blood!"},\n    {"Stitches", "Patient is `6losing blood!"},\n    {"FixIt", "Incisions: `20"}, {"FixIt", "Incisions: `30"},\n    {"Ultrasound", "The patient has not been diagnosed."},\n    {"Anesthetic", "Status: `4Awake"},\n    {"Splint", "Bones: `[46][^\\n]-broken"},\n    {"Stitches", "Patient broke his arm."},\n    {"Anesthetic", "Status: `3Awake"},\n    {"Transfusion", "Pulse: `6"},\n    {"Sponge", "`4You can\'t see what you are doing!"},\n    {"Stitches", "tool1296"},\n    {"Pins", "Bones: `[46][^\\n]-shattered"},\n    {"Scalpel", "Bones: `[46][^\\n]-shattered"},\n    {"Stitches", "Patient broke his leg."},\n    {"Clamp", "Patient is losing blood `3slowly."},\n    {"Scalpel", nil}\n}\n\nlocal cfg = {\n    surgery=false, pathfind=false, tea=true, spice=true,\n    stop_low=false, restock=false, caduceus=true\n}\nlocal last_text, last_time = "", 0\nlocal last_prep_signature = ""\nlocal function note(msg)\n    if growtopia and type(growtopia.notify) == "function" then\n        pcall(growtopia.notify, tostring(msg))\n    elseif type(LogToConsole) == "function" then\n        LogToConsole("`9[ZS Surg] `w" .. tostring(msg))\n    end\nend\nlocal function inv(id)\n    if growtopia and type(growtopia.checkInventoryCount) == "function" then\n        local ok, n = pcall(growtopia.checkInventoryCount, id)\n        if ok then return tonumber(n) or 0 end\n    end\n    return 0\nend\nlocal function itemID(name, fallback)\n    if growtopia and type(growtopia.getItemID) == "function" then\n        local ok, id = pcall(growtopia.getItemID, name)\n        if ok and tonumber(id) and tonumber(id) > 0 then return tonumber(id) end\n    end\n    return fallback\nend\nlocal function offered(text, id)\n    return text:find("tool" .. id, 1, true) ~= nil\nend\nlocal function choose(text)\n    for _, rule in ipairs(RULES) do\n        local id = TOOL[rule[1]]\n        if offered(text, id) and (rule[2] == nil or text:find(rule[2])) then\n            return rule[1], id\n        end\n    end\nend\nlocal function sendUseItem(id)\n    -- Tank packet 10 is Growtopia\'s item-activation request.\n    if type(SendPacketRaw) == "function" then\n        local ok = pcall(SendPacketRaw, false, {type=10, value=id})\n        if ok then return true end\n    end\n    if type(sendPacketRaw) == "function" then\n        local ok = pcall(sendPacketRaw, false, {type=10, value=id})\n        if ok then return true end\n    end\n    return false\nend\n\n-- "FixIt" (1296) is Surgical Gloves: the icon of the "Fix it!" button, UNOBTAINABLE by players\n-- (growtopiawiki.com/w/Guide:Surgery). Its inventory count is always 0, which made the old\n-- check think a tool was "< 10" all the time and sent the bot to the storage world.\nlocal NOT_OBTAINABLE = { FixIt = true }\nlocal function invRaw(id)\n    if growtopia and type(growtopia.checkInventoryCount) == "function" then\n        local ok, n = pcall(growtopia.checkInventoryCount, id)\n        if ok and tonumber(n) then return tonumber(n) end\n    end\n    return nil   -- API failed: unknown, NOT zero\nend\n-- A tool only counts as "low" once we have actually seen it in the inventory (or used it)\n-- since AUTO SURG was turned on. Tools the player never carries are ignored.\nlocal seenTool = {}\nlocal function checkTools(all)\n    local low = {}\n    for name, id in pairs(TOOL) do\n        if not NOT_OBTAINABLE[name] then\n            local n = invRaw(id)\n            if n then\n                if n > 0 then seenTool[name] = true end\n                if n < 10 and (all or seenTool[name]) then low[#low+1] = name .. "=" .. n end\n            end\n        end\n    end\n    table.sort(low)\n    return low\nend\n\n-- AUTO WRENCH state (added): wrench the Surg-E automatically once we are next to it.\nlocal WRENCH_ID = 32\nlocal last_wrench, last_tool_dialog, last_path = 0, 0, 0\nlocal TEA_INTERVAL_MS = 2 * 60 * 1000\nlocal TEA_ID = itemID("Tea", 5118)   -- Tea (drop of Tea Set 5116 = 5118). 5114 was WRONG. Name lookup wins.\nlocal last_tea = -TEA_INTERVAL_MS\nlocal SPICE_INTERVAL_MS = 30 * 60 * 1000   -- Skill Spice mod lasts 30 min\nlocal SPICE_ID = itemID("Skill Spice", 6912)   -- name lookup first, 6912 as fallback\n\n-- Robust consumable finder: scans the REAL inventory by item NAME first (so a wrong\n-- hard-coded id can never break it), then falls back to the known ids.\nlocal function zs_inventory_items()\n    local list = {}\n    local getter = (type(GetInventory) == "function" and GetInventory)\n        or (type(getInventory) == "function" and getInventory)\n    if getter then\n        local ok, invt = pcall(getter)\n        if ok and type(invt) == "table" then\n            for _, it in pairs(invt) do\n                local id = tonumber(it.id or it.itemID or it.itemid)\n                local amt = tonumber(it.amount or it.count) or 0\n                if id and id > 0 and amt > 0 then list[#list + 1] = { id = id, amount = amt } end\n            end\n        end\n    end\n    return list\nend\nlocal function zs_item_name(id)\n    if growtopia and type(growtopia.getItemName) == "function" then\n        local ok, nm = pcall(growtopia.getItemName, id)\n        if ok and nm then return tostring(nm) end\n    end\n    return ""\nend\n-- exactNames: lower-case names that must match exactly; fuzzy: lower-case substring fallback.\nlocal function zs_find_consumable(exactNames, fuzzy, fallbackIds)\n    local items = zs_inventory_items()\n    local fuzzyHit\n    for _, it in ipairs(items) do\n        local nm = zs_item_name(it.id):lower()\n        for _, ex in ipairs(exactNames) do\n            if nm == ex then return it.id, it.amount end\n        end\n        if not fuzzyHit and fuzzy and nm ~= "" and nm:find(fuzzy, 1, true) then\n            fuzzyHit = it\n        end\n    end\n    if fuzzyHit then return fuzzyHit.id, fuzzyHit.amount end\n    for _, id in ipairs(fallbackIds) do\n        if id and inv(id) > 0 then return id, inv(id) end\n    end\n    return nil, 0\nend\nlocal function zs_find_tea()\n    return zs_find_consumable({ "tea" }, nil, { TEA_ID, 5118, 5114 })\nend\nlocal function zs_find_spice()\n    return zs_find_consumable({ "skill spice", "spice" }, "spice", { SPICE_ID, 6912 })\nend\nlocal last_spice = -SPICE_INTERVAL_MS\nlocal SURGE_FAIL_COOLDOWN_MS = 3 * 60 * 1000\nlocal surge_fail_at = -SURGE_FAIL_COOLDOWN_MS\nlocal function nowms()\n    -- wall-clock milliseconds (1 s resolution). getTime()\'s unit is not guaranteed and\n    -- os.clock() is CPU time, so a "2 minute" timer built on them could never fire.\n    if type(os) == "table" and type(os.time) == "function" then return os.time() * 1000 end\n    return (type(getTime) == "function" and getTime()) or os.clock() * 1000\nend\nlocal wrenchX, wrenchY = nil, nil\nlocal function wrenchTile(x, y)\n    wrenchX, wrenchY = x, y\n    local p = type(GetLocal) == "function" and GetLocal() or nil\n    if not p then return false end\n    local pkt = {x = p.posX, y = p.posY, px = x, py = y, type = 3, value = WRENCH_ID}\n    if type(SendPacketRaw) == "function" and pcall(SendPacketRaw, false, pkt) then return true end\n    if type(sendPacketRaw) == "function" and pcall(sendPacketRaw, false, pkt) then return true end\n    return false\nend\n-- Clicks the "start / operate" button of the Surg-E dialog that opens after a wrench.\nlocal START_WORDS = {"start", "operate", "begin", "perform", "surgery", "surgeon", "patient", "accept", "yes", "ok"}\nlocal STOP_WORDS  = {"cancel", "close", "back", "no", "exit", "leave"}\nlocal function handleSurgEDialog(text)\n    -- end_dialog|<name>|<cancel label>|<ok label>|\n    local dname, cancelLbl, okLbl = text:match("end_dialog|([^|\\n]*)|([^|\\n]*)|([^|\\n]*)")\n    dname = dname or text:match("end_dialog|([^|]*)|") or ""\n    local best\n    for bname, label in text:gmatch("add_button|([^|]*)|([^|]*)|") do\n        local hay = (bname .. " " .. label):lower()\n        local bad = false\n        for _, w in ipairs(STOP_WORDS) do if hay:find(w, 1, true) then bad = true end end\n        if not bad then\n            for _, w in ipairs(START_WORDS) do\n                if hay:find(w, 1, true) then best = best or bname end\n            end\n        end\n    end\n    -- debug: shows the dialog in the console so the right button name can be checked\n    if type(LogToConsole) == "function" then\n        LogToConsole("`9[ZS Surg] `wSurg-E dialog: name=" .. dname .. " button=" .. tostring(best)\n            .. " ok=" .. tostring(okLbl))\n        LogToConsole("`9[ZS Surg] `wraw: " .. text:gsub("\\n", " / "):sub(1, 400))\n    end\n    if type(SendPacket) ~= "function" then return false end\n    if best then\n        pcall(SendPacket, 2, "action|dialog_return\\ndialog_name|" .. dname .. "\\nbuttonClicked|" .. best)\n        return true\n    end\n    -- No named start button: the dialog is a plain one, so press its OK button.\n    -- The real client echoes every embed_data field (tilex/tiley) back with OK.\n    if dname ~= "" then\n        local extra, seen = "", {}\n        for k, v in text:gmatch("embed_data|([^|\\n]*)|([^|\\n]*)") do\n            extra = extra .. k .. "|" .. v .. "\\n"\n            seen[k] = true\n        end\n        if not seen.tilex and wrenchX then extra = extra .. "tilex|" .. wrenchX .. "\\n" end\n        if not seen.tiley and wrenchY then extra = extra .. "tiley|" .. wrenchY .. "\\n" end\n        pcall(SendPacket, 2, "action|dialog_return\\ndialog_name|" .. dname .. "\\n" .. extra .. "buttonClicked|\\n")\n        if type(LogToConsole) == "function" then\n            LogToConsole("`9[ZS Surg] `wPressed Okay on " .. dname .. " (" .. extra:gsub("\\n", " ") .. ")")\n        end\n        return true\n    end\n    return false\nend\n\nlocal function findSurgE()\n    local tiles\n    if type(GetTiles) == "function" then\n        local ok, result = pcall(GetTiles)\n        if ok and type(result) == "table" then tiles = result end\n    elseif type(getTiles) == "function" then\n        local ok, result = pcall(getTiles)\n        if ok and type(result) == "table" then tiles = result end\n    end\n    if not tiles then return nil end\n    for _, t in pairs(tiles) do\n        if tonumber(t.fg) == 4296 then return tonumber(t.x), tonumber(t.y) end\n    end\n    return nil\nend\n\n-- AUTO LEGAL BRIEFS: ONLY right after a surgery FAILED (license revoked etc.),\n-- and only if Legal Briefs are in the inventory: use them twice, then surgery continues.\nlocal legal_busy, last_legal = false, 0\nlocal LEGAL_NAMES = { "Legal Briefs", "Legal Brief" }\nlocal function findLegal()\n    for _, nm in ipairs(LEGAL_NAMES) do\n        local id = itemID(nm, nil)\n        if id and inv(id) > 0 then return id, inv(id) end\n    end\n    if inv(3172) > 0 then return 3172, inv(3172) end\n    return nil, 0\nend\nlocal PANTS_NAMES = { "Blingin\' Pants", "Blingin Pants", "Blingin\\226\\128\\153 Pants" }\nlocal function findBlinginPants()\n    for _, nm in ipairs(PANTS_NAMES) do\n        local id = itemID(nm, nil)\n        if id and inv(id) > 0 then return id, nm end\n    end\n    return nil\nend\n-- Only the real "surgery failed" messages (growtopiawiki.com/w/Guide:Surgery, "Surgery Success and Failure").\nlocal FAIL_PATTERNS = {\n    "medical license is revoked",\n    "put the patient to sleep. permanently",\n    "you couldn\'t save them",\n    "you abandoned your patient",\n    "smashed your surgical robot",\n}\n-- Surg-E warns about an existing malpractice record BEFORE/while starting surgery\n-- (e.g. "...the authorities don\'t even trust you operating on that with your\n-- malpractice issues."). Apostrophes are avoided on purpose (straight vs curly).\nlocal MALPRACTICE_PATTERNS = {\n    "malpractice issues",\n    "with your malpractice",\n    "authorities don",\n}\nlocal function legalCheck(event, text)\n    if not cfg.surgery then return end\n    if not (event:find("OnConsoleMessage", 1, true) or event:find("OnTalkBubble", 1, true)) then return end\n    local low = text:lower()\n    -- other players\' chat lines are never a surgery failure\n    if low:find("_oid:", 1, true) or low:find("_ct:", 1, true) then return end\n    local failed, malpractice\n    for _, pat in ipairs(MALPRACTICE_PATTERNS) do\n        if low:find(pat, 1, true) then failed = pat malpractice = true break end\n    end\n    if not failed then\n        -- a surgery must have been running a moment ago\n        if last_tool_dialog <= 0 or (nowms() - last_tool_dialog) > 60000 then return end\n        for _, pat in ipairs(FAIL_PATTERNS) do\n            if low:find(pat, 1, true) then failed = pat break end\n        end\n    end\n    if not failed then return end\n    local clock = nowms()\n    if legal_busy or (clock - last_legal) < 20000 then return end\n    local id, n = findLegal()\n    if type(LogToConsole) == "function" then\n        LogToConsole("`9[ZS Surg] `wSurgery failed (" .. tostring(failed) .. "). Legal Briefs id=" .. tostring(id) .. " count=" .. tostring(n))\n    end\n    if not id then note("Surgery failed but there are no Legal Briefs in inventory."); return end\n    legal_busy = true\n    last_legal = clock\n    ZS_thread(function()\n        -- Use once, then check if it was consumed; use again only if still available.\n        local before = inv(id)\n        sendUseItem(id)\n        Sleep(1000)\n        if inv(id) >= before and before > 1 then\n            sendUseItem(id)\n            Sleep(1000)\n        end\n        -- Legal Briefs take the pants slot: ALWAYS put Blingin\' Pants back on.\n        local pid, pname = findBlinginPants()\n        if pid then\n            sendUseItem(pid)\n            Sleep(800)\n            if type(LogToConsole) == "function" then\n                LogToConsole("`9[ZS Surg] `wBlingin Pants equipped again (" .. tostring(pname) .. ", id=" .. tostring(pid) .. ").")\n            end\n        else\n            note("Blingin Pants not found in inventory - could not put them back on.")\n        end\n        legal_busy = false\n        last_wrench = 0   -- wrench the Surg-E again right away and continue surgery\n        note("Legal Briefs used. Continuing surgery.")\n    end)\nend\n\nlocal function surgery_hook(var)\n    if type(var) ~= "table" then return false end\n    local event = tostring(var.v1 or var[0] or "")\n    local text = tostring(var.v2 or var[1] or "")\n    legalCheck(event, text .. " " .. tostring(var.v3 or var[2] or "") .. " " .. tostring(var.v4 or var[3] or ""))\n    if not event:find("OnDialogRequest", 1, true) then return false end\n\n    if cfg.surgery and not text:find("tool%d%d%d%d") then\n        -- Dialog opened by our wrench (Surg-E menu): auto-press the start button.\n        local isSurgE = text:find("perform surgery on this robot", 1, true)\n            or text:find("Anatomical Dummy", 1, true)\n            or text:find("Surg%-E")\n        local afterWrench = (nowms() - last_wrench) < 3000\n        if (isSurgE or afterWrench) and not text:find("drop_item", 1, true) then\n            return handleSurgEDialog(text)\n        end\n        return false\n    end\n    if not cfg.surgery then return false end\n    last_tool_dialog = nowms()\n\n    if cfg.stop_low then\n        local low = checkTools()\n        if #low > 0 then\n            cfg.surgery = false\n            if type(setValue) == "function" then pcall(setValue, "zs_surgery_toggle", false) end\n            note("AUTO SURG stopped: tool below 10 (" .. table.concat(low, ", ") .. ")")\n            return false\n        end\n    end\n\n    local now = (type(getTime) == "function" and getTime()) or os.clock()*1000\n    if text == last_text and (now - last_time) < 120 then return true end\n    local name, id = choose(text)\n    if not id then return false end\n    last_text, last_time = text, now\n    seenTool[name] = true\n    if type(SendPacket) == "function" then\n        local ok = pcall(SendPacket, 2,\n            "action|dialog_return\\ndialog_name|surgery\\nbuttonClicked|tool" .. id)\n        if ok and type(LogToConsole) == "function" then\n            LogToConsole("`9[ZS Auto Surg] `c" .. name)\n        end\n        return ok\n    end\n    return false\nend\n\nfunction zs_set_surgery_enabled(value)\n    cfg.surgery = value and true or false\n    -- One switch now controls both automatic tool selection and Surg-E approach.\n    cfg.pathfind = cfg.surgery\n    if cfg.surgery then\n        seenTool = {}\n        checkTools()                 -- remember which tools we really carry\n        last_tea = -TEA_INTERVAL_MS  -- first Tea right away, then every 2 min\n        last_spice = -SPICE_INTERVAL_MS  -- first Skill Spice right away, then every 30 min\n        surge_fail_at = -SURGE_FAIL_COOLDOWN_MS  -- scan for Surg-E right away\n    end\n    note(cfg.surgery and "AUTO SURG V2: ON (tool selection + Surg-E pathfinding)" or "AUTO SURG V2: OFF")\nend\nfunction zs_set_surgery_option(name, value)\n    if cfg[name] ~= nil then\n        cfg[name] = value and true or false\n        if cfg[name] and name == "tea" then last_tea = -TEA_INTERVAL_MS end\n        if cfg[name] and name == "spice" then last_spice = -SPICE_INTERVAL_MS end\n        note(name:upper() .. (cfg[name] and ": ON" or ": OFF"))\n    end\nend\nfunction zs_surgery_pathfind()\n    local x, y = findSurgE()\n    if not x then note("No placed Surg-E found in this world."); return end\n    if type(FindPath) == "function" then\n        FindPath(x, y)\n        note("Pathfinding directly to Surg-E at " .. x .. "," .. y)\n    else\n        note("FindPath API unavailable.")\n    end\nend\nfunction zs_surgery_check_tools()\n    local low = checkTools(true)\n    if #low == 0 then note("All surgery tools are at least 10.")\n    else note("Below 10: " .. table.concat(low, ", ")) end\nend\nfunction zs_surgery_convert_caduceus()\n    local id = itemID("Caduceus", 4298)\n    local n = inv(id)\n    if n < 100 then note("Need 100 Caduceus; inventory has " .. n .. "."); return end\n    if sendUseItem(id) then note("Caduceus conversion requested (100 -> 1 Golden Caduceus).")\n    else note("Could not send item activation packet.") end\nend\nfunction zs_surgery_use_tea()\n    local id = zs_find_tea()\n    if not id then note("No Tea in inventory."); return end\n    if sendUseItem(id) then note("Tea use requested.") else note("Item activation API unavailable.") end\nend\nfunction zs_surgery_use_spice()\n    local id = zs_find_spice()\n    if not id then note("No Skill Spice in inventory."); return end\n    if sendUseItem(id) then note("Skill Spice use requested.") else note("Item activation API unavailable.") end\nend\nfunction zs_surgery_place_surge()\n    local p = type(GetLocal) == "function" and GetLocal() or nil\n    if not p then note("Player data unavailable."); return end\n    local id = itemID("Surg-E", 4296)\n    if inv(id) < 1 then note("No Surg-E in inventory."); return end\n    local tx, ty = math.floor((p.posX or 0)/32), math.floor((p.posY or 0)/32)\n    local tile = type(GetTile) == "function" and GetTile(tx, ty) or nil\n    if tile and tonumber(tile.fg or 0) ~= 0 then\n        note("Your current tile is occupied. Move to an empty tile and try again.")\n        return\n    end\n    if type(SendPacketRaw) == "function" then\n        local ok = pcall(SendPacketRaw, false, {\n            type=3, value=id, px=tx, py=ty, x=p.posX, y=p.posY\n        })\n        note(ok and "Surg-E placement request sent." or "Could not send placement packet.")\n    else note("SendPacketRaw API unavailable.") end\nend\nfunction zs_surgery_legal_brief_help()\n    local id = itemID("Legal Briefs", 3172)\n    if inv(id) < 1 then note("No Legal Briefs in inventory."); return end\n    note("Legal Briefs remove Malpractice when equipped. Equip them manually from inventory; auto-equipping is not enabled because the launcher docs do not specify a safe equip call.")\nend\n\n-- AUTO TOOL RESTOCK: when a surgery tool is below 10 and a Surgery storage world\n-- is written in the box, go there, pick up the dropped tools, then return.\nlocal TOOL_TARGET = 200\nlocal RESTOCK_COOLDOWN_MS = 3 * 60 * 1000\nlocal last_restock = -RESTOCK_COOLDOWN_MS\nlocal restocking = false\n\nlocal function currentWorld()\n    if type(GetWorldName) == "function" then\n        local ok, w = pcall(GetWorldName)\n        if ok and w then return tostring(w) end\n    end\n    return nil\nend\nlocal function waitWorld(name, timeout)\n    local waited = 0\n    while waited < timeout do\n        local w = currentWorld()\n        if w and w:upper() == name:upper() then return true end\n        Sleep(100)\n        waited = waited + 100\n    end\n    local w = currentWorld()\n    return w ~= nil and w:upper() == name:upper()\nend\nlocal function worldObjects()\n    local objects\n    if type(GetObjects) == "function" then\n        local ok, r = pcall(GetObjects)\n        if ok and type(r) == "table" then objects = r end\n    end\n    if not objects and type(GetObjectList) == "function" then\n        local ok, r = pcall(GetObjectList)\n        if ok and type(r) == "table" then objects = r end\n    end\n    return objects or {}\nend\nlocal function scanDroppedTools(isTool)\n    local list = {}\n    for _, obj in pairs(worldObjects()) do\n        local id = tonumber(obj and (obj.itemid or obj.itemID or obj.item_id or obj.id))\n        local pos = obj and (obj.pos or obj.position)\n        local ox = tonumber((pos and (pos.x or pos.posX)) or (obj and (obj.x or obj.posX)))\n        local oy = tonumber((pos and (pos.y or pos.posY)) or (obj and (obj.y or obj.posY)))\n        if id and isTool[id] and ox and oy then\n            list[#list + 1] = { id = id, x = math.floor(ox / 32), y = math.floor(oy / 32) }\n        end\n    end\n    return list\nend\n-- Same pickup rhythm/speed as the Provider / Science collect: ModFly ON while collecting,\n-- FindPath -> delayf (75 ms) -> range check -> delayp (110 ms).\nlocal PICK_DELAYF = 75\nlocal PICK_DELAYP = 110\nlocal function nearTile(tx, ty)\n    local pl = type(GetLocal) == "function" and GetLocal() or nil\n    if not pl then return false end\n    local px = (pl.posX or (pl.pos and pl.pos.x) or 0) / 32\n    local py = (pl.posY or (pl.pos and pl.pos.y) or 0) / 32\n    return math.abs(px - tx) <= 1 and math.abs(py - ty) <= 1\nend\nlocal function takeDroppedToolsInner(isTool, target)\n    -- Wait only as long as the world objects need to load (no fixed 800 ms sleep).\n    local list, waited = scanDroppedTools(isTool), 0\n    while #list == 0 and waited < 3000 do\n        Sleep(120); waited = waited + 120\n        list = scanDroppedTools(isTool)\n    end\n    if #list == 0 or type(FindPath) ~= "function" then return end\n\n    local startClock = os.clock()\n    local pl = type(GetLocal) == "function" and GetLocal() or nil\n    local cx = pl and math.floor((pl.posX or 0) / 32) or 0\n    local cy = pl and math.floor((pl.posY or 0) / 32) or 0\n    for pass = 1, 2 do\n        while #list > 0 and (os.clock() - startClock) < 30 do\n            -- nearest drop first (shortest walk), skip items that already reached the target\n            for i = #list, 1, -1 do\n                if inv(list[i].id) >= target then table.remove(list, i) end\n            end\n            local bi, bd\n            for i = 1, #list do\n                local d = math.abs(list[i].x - cx) + math.abs(list[i].y - cy)\n                if not bd or d < bd then bi, bd = i, d end\n            end\n            if not bi then break end\n            local o = table.remove(list, bi)\n            local before = inv(o.id)\n            if o.x ~= cx or o.y ~= cy then FindPath(o.x, o.y) end\n            cx, cy = o.x, o.y\n            Sleep(PICK_DELAYF)\n            -- wait until we are really on the drop (only if FindPath returned early)\n            local w = 0\n            while not nearTile(o.x, o.y) and w < 1500 do Sleep(50); w = w + 50 end\n            -- pickup wait: leave as soon as the count goes up (max delayp + 140 ms)\n            local w2 = 0\n            while w2 < (PICK_DELAYP + 140) and inv(o.id) <= before do Sleep(25); w2 = w2 + 25 end\n        end\n        if pass == 1 then list = scanDroppedTools(isTool) end   -- one quick re-scan for missed drops\n    end\nend\nlocal function parseStorageWorlds(raw)\n    local out, seen = {}, {}\n    for w in tostring(raw or ""):gmatch("[^,;%s]+") do\n        local u = w:upper()\n        if not seen[u] then seen[u] = true; out[#out + 1] = u end\n    end\n    return out\nend\nlocal function toolIdSet()\n    local set = {}\n    for name, id in pairs(TOOL) do\n        if not NOT_OBTAINABLE[name] then set[id] = true end\n    end\n    return set\nend\nlocal SURGE_ID = 4296   -- Surg-E\nlocal function takeDropped(isSet, target)\n    pcall(EditToggle, "ModFly", true)      -- the fast "little guy" movement the Provider uses\n    -- called directly (NOT inside pcall): pcall can break Sleep()/FindPath() waits on some launchers\n    takeDroppedToolsInner(isSet, target)\n    pcall(EditToggle, "ModFly", false)\nend\n\n-- Visits the storage worlds one by one (MULTIWORLD), picks up the wanted drops, stops as soon as\n-- doneFn() says we have enough, then returns to the home world. Returns true when back home.\nlocal function runStorageTrip(worlds, doneFn, itemSet, target)\n    if not growtopia or type(growtopia.warpTo) ~= "function" then\n        note("Cannot go to storage: warp API unavailable.")\n        return false\n    end\n    local home = currentWorld()\n    if not home or home == "" or home == "EXIT" then return false end\n    for _, w in ipairs(worlds) do\n        if not cfg.surgery then break end\n        local cur = currentWorld()\n        local entered = cur ~= nil and cur:upper() == w\n        if not entered then\n            growtopia.warpTo(w)\n            entered = waitWorld(w, 15000)\n            if not entered then note("Could not enter storage world " .. w .. ", trying the next one.") end\n        end\n        if entered then\n            Sleep(150)\n            takeDropped(itemSet, target)\n            if doneFn() then break end\n        end\n    end\n    local cur = currentWorld()\n    if not (cur and cur:upper() == home:upper()) then\n        growtopia.warpTo(home)\n        if not waitWorld(home, 15000) then\n            note("Could not return to " .. home)\n            return false\n        end\n    end\n    Sleep(300)\n    return true\nend\n\nlocal function storageWorlds()\n    local raw = type(getValue) == "function" and getValue(2, "zs_surgery_storage_world") or ""\n    return parseStorageWorlds(raw)\nend\n\nlocal function restockTools()\n    if restocking then return end\n    -- MULTIWORLD: "Surgery storage world" may hold several worlds separated by commas.\n    local worlds = storageWorlds()\n    if #worlds == 0 then return end\n    local low = checkTools()\n    if #low == 0 then return end\n    if (nowms() - last_restock) < RESTOCK_COOLDOWN_MS then return end\n    -- Confirm: read the inventory again after a moment so a single bad read never sends us away.\n    Sleep(1000)\n    if not cfg.surgery or (nowms() - last_tool_dialog) <= 6000 then return end\n    low = checkTools()\n    if #low == 0 then return end\n    last_restock = nowms()\n    local home = currentWorld()\n    if not home or home == "" or home == "EXIT" then return end\n\n    restocking = true\n    note("Tools low (" .. table.concat(low, ", ") .. "). Storage worlds: " .. table.concat(worlds, ", "))\n    local back = runStorageTrip(worlds, function() return #checkTools() == 0 end, toolIdSet(), TOOL_TARGET)\n    if back then\n        local still = checkTools()\n        if #still == 0 then\n            note("Tools restocked. Continuing surgery.")\n        else\n            note("Tools taken. Still below 10: " .. table.concat(still, ", "))\n        end\n    end\n    restocking = false\nend\n\n-- ==========================================================\n-- AUTO SURG-E: when AUTO SURG is ON and the world has no Surg-E left:\n--   1) Surg-E in the inventory -> place them\n--   2) none in the inventory   -> fetch from the storage world(s) (up to 200)\n--   3) place them left -> right (up to 200) and keep operating\n-- ==========================================================\nlocal SURGE_MAX = 200\nlocal SURGE_PLACE_DELAY = 110\nlocal provisioning = false\n\nlocal function worldTilesList()\n    local tiles\n    if type(GetTiles) == "function" then\n        local ok, r = pcall(GetTiles)\n        if ok and type(r) == "table" then tiles = r end\n    elseif type(getTiles) == "function" then\n        local ok, r = pcall(getTiles)\n        if ok and type(r) == "table" then tiles = r end\n    end\n    return tiles\nend\n-- number of placed Surg-E in this world, or nil when the tile list is unavailable\nlocal function worldSurgECount()\n    local tiles = worldTilesList()\n    if not tiles or next(tiles) == nil then return nil end\n    local n = 0\n    for _, t in pairs(tiles) do\n        if tonumber(t.fg) == SURGE_ID then n = n + 1 end\n    end\n    return n\nend\nlocal function tileFgAt(x, y)\n    if type(GetTile) ~= "function" then return nil end\n    local ok, t = pcall(GetTile, x, y)\n    if ok and t then return tonumber(t.fg) or 0 end\n    return nil\nend\nlocal function sendPlace(id, x, y)\n    local pl = type(GetLocal) == "function" and GetLocal() or nil\n    if not pl or type(SendPacketRaw) ~= "function" then return false end\n    return pcall(SendPacketRaw, false, { x = pl.posX, y = pl.posY, px = x, py = y, type = 3, value = id })\nend\n\n-- Empty tiles with solid ground below, ordered: player\'s row first, then the nearest rows,\n-- each row left -> right.\nlocal function surgeCandidates(limit)\n    local tiles = worldTilesList()\n    if not tiles then return {} end\n    local fgmap = {}\n    for _, t in pairs(tiles) do\n        local x, y = tonumber(t.x), tonumber(t.y)\n        if x and y then\n            x, y = math.floor(x), math.floor(y)\n            fgmap[y] = fgmap[y] or {}\n            fgmap[y][x] = tonumber(t.fg) or 0\n        end\n    end\n    local pl = type(GetLocal) == "function" and GetLocal() or nil\n    local py = pl and math.floor((pl.posY or 0) / 32) or 0\n    local list = {}\n    for y, row in pairs(fgmap) do\n        local below = fgmap[y + 1]\n        if below then\n            for x, fg in pairs(row) do\n                local bfg = below[x]\n                if fg == 0 and bfg and bfg > 0 and bfg ~= 6 and bfg % 2 == 0 then\n                    list[#list + 1] = { x = x, y = y }\n                end\n            end\n        end\n    end\n    table.sort(list, function(a, b)\n        local da, db = math.abs(a.y - py), math.abs(b.y - py)\n        if da ~= db then return da < db end\n        if a.y ~= b.y then return a.y < b.y end\n        return a.x < b.x\n    end)\n    local out = {}\n    for i = 1, math.min(#list, limit) do out[i] = list[i] end\n    return out\nend\n\nlocal function placeSurgEs(count)\n    local cands = surgeCandidates(count)\n    if #cands == 0 then note("No free tiles to place Surg-E."); return 0 end\n    local placed, startClock, i = 0, os.clock(), 1\n    while i <= #cands and cfg.surgery and (os.clock() - startClock) < 180 do\n        if inv(SURGE_ID) <= 0 then break end\n        -- group up to 3 neighbouring tiles of the same row (same pattern as Auto Plant)\n        local first = cands[i]\n        local group = { first }\n        local j = i + 1\n        while j <= #cands and #group < 3 and cands[j].y == first.y and cands[j].x <= first.x + 2 do\n            group[#group + 1] = cands[j]\n            j = j + 1\n        end\n        i = j\n        if not nearTile(first.x + 1, first.y) then\n            if type(FindPath) == "function" then FindPath(first.x + 1, first.y) end\n            Sleep(PICK_DELAYF)\n        end\n        for _, t in ipairs(group) do\n            sendPlace(SURGE_ID, t.x, t.y)\n            Sleep(SURGE_PLACE_DELAY)\n        end\n        Sleep(SURGE_PLACE_DELAY)\n        for _, t in ipairs(group) do\n            local fg = tileFgAt(t.x, t.y)\n            if fg == SURGE_ID then\n                placed = placed + 1\n            elseif inv(SURGE_ID) > 0 then      -- one retry for a missed placement\n                sendPlace(SURGE_ID, t.x, t.y)\n                Sleep(SURGE_PLACE_DELAY)\n                if tileFgAt(t.x, t.y) == SURGE_ID then placed = placed + 1 end\n            end\n        end\n    end\n    return placed\nend\n\nlocal function ensureSurgE()\n    if provisioning or restocking then return end\n    local cnt = worldSurgECount()\n    if cnt == nil or cnt > 0 then return end\n    if (nowms() - surge_fail_at) < SURGE_FAIL_COOLDOWN_MS then return end\n    Sleep(800)                      -- confirm: a Surg-E that just broke can be replaced by the scan\n    cnt = worldSurgECount()\n    if cnt == nil or cnt > 0 then return end\n\n    provisioning = true\n    pcall(EditToggle, "ModFly", true)\n    local have = inv(SURGE_ID)\n    if have <= 0 then\n        local worlds = storageWorlds()\n        if #worlds > 0 then\n            note("No Surg-E in the world or inventory. Fetching from storage: " .. table.concat(worlds, ", "))\n            runStorageTrip(worlds, function() return inv(SURGE_ID) >= SURGE_MAX end,\n                { [SURGE_ID] = true }, SURGE_MAX)\n            -- tile list of the home world needs a moment after the warp\n            local w = 0\n            while worldSurgECount() == nil and w < 3000 do Sleep(150); w = w + 150 end\n            have = inv(SURGE_ID)\n        else\n            note("No Surg-E in the world or inventory, and no Surgery storage world is set.")\n        end\n    end\n    if have > 0 and cfg.surgery then\n        local n = placeSurgEs(math.min(have, SURGE_MAX))\n        note("Placed " .. n .. " Surg-E. Continuing surgery.")\n        if n <= 0 then surge_fail_at = nowms() end\n    elseif have <= 0 then\n        note("No Surg-E found anywhere. Will retry in 3 minutes.")\n        surge_fail_at = nowms()\n    end\n    pcall(EditToggle, "ModFly", false)\n    last_wrench = 0\n    provisioning = false\nend\n\n-- When Tea / Skill Spice runs out, switch that one toggle OFF (the other keeps running).\nlocal function turnOffConsumable(optionName, toggleAlias, label)\n    cfg[optionName] = false\n    if type(setValue) == "function" then pcall(setValue, toggleAlias, false) end\n    note(label .. " ran out: AUTO " .. label:upper() .. " turned OFF.")\nend\n\n-- AUTO TEA: while AUTO SURG is ON, drink Tea every 2 minutes (halves skill-fail chance).\n-- If there is no Tea in the inventory: warn, but keep surgery running and retry next cycle.\nlocal function autoTea()\n    local t = nowms()\n    if (t - last_tea) < TEA_INTERVAL_MS then return end\n    last_tea = t\n    local tid, before = zs_find_tea()\n    if tid and before > 0 then\n        TEA_ID = tid\n        local sent = sendUseItem(tid)\n        Sleep(1200)\n        local after = inv(tid)\n        if type(LogToConsole) == "function" then\n            LogToConsole("`9[ZS Surg] `wTea used. id=" .. tostring(tid) .. " sent=" .. tostring(sent)\n                .. " tea " .. before .. " -> " .. after)\n        end\n    else\n        note("No Tea found in inventory - surgery continues, will retry in 2 min.")\n    end\nend\n\n-- AUTO SKILL SPICE: while AUTO SURG is ON, use Skill Spice again every 30 minutes (its mod lasts 30 min).\n-- If there is no Skill Spice: warn, keep surgery running and retry next cycle.\nlocal function autoSpice()\n    local t = nowms()\n    if (t - last_spice) < SPICE_INTERVAL_MS then return end\n    last_spice = t\n    local sid, before = zs_find_spice()\n    if sid and before > 0 then\n        SPICE_ID = sid\n        local sent = sendUseItem(sid)\n        Sleep(1200)\n        local after = inv(sid)\n        if type(LogToConsole) == "function" then\n            LogToConsole("`9[ZS Surg] `wSkill Spice used. id=" .. tostring(sid) .. " sent=" .. tostring(sent)\n                .. " spice " .. before .. " -> " .. after)\n        end\n    else\n        note("No Skill Spice found in inventory - surgery continues, will retry in 30 min.")\n    end\nend\n\n-- AUTO GOLDEN CADUCEUS: while AUTO SURG is ON, as soon as the inventory holds\n-- 100 Caduceus, use them to convert 100 -> 1 Golden Caduceus.\nlocal CADUCEUS_ID = 4298\nlocal last_caduceus = 0\nlocal function autoCaduceus()\n    local t = nowms()\n    if (t - last_caduceus) < 5000 then return end\n    local before = inv(CADUCEUS_ID)\n    if before < 100 then return end\n    last_caduceus = t\n    local sent = sendUseItem(CADUCEUS_ID)\n    Sleep(1500)\n    local after = inv(CADUCEUS_ID)\n    if type(LogToConsole) == "function" then\n        LogToConsole("`9[ZS Surg] `wCaduceus converted. sent=" .. tostring(sent)\n            .. " caduceus " .. before .. " -> " .. after)\n    end\n    note("100 Caduceus -> Golden Caduceus.")\nend\n\n-- Growlauncher 7.0.1+ uses lowercase hook event names.\naddHook(surgery_hook, "onvariant")\n\n-- Optional Surg-E scanner. It only moves when the toggle is enabled.\nlocal pathfind_loop_started = false\nlocal function zs_surgery_path_loop()\n    if pathfind_loop_started then return end\n    pathfind_loop_started = true\n    ZS_thread(function()\n        while true do\n            if cfg.surgery and cfg.tea and not restocking then autoTea() end\n            if cfg.surgery and cfg.spice and not restocking then autoSpice() end\n            if cfg.surgery and cfg.caduceus and not restocking then autoCaduceus() end\n            if cfg.surgery and cfg.restock and not restocking and (nowms() - last_tool_dialog) > 6000 then\n                restockTools()\n            end\n            if cfg.surgery and cfg.pathfind and not restocking and (nowms() - last_tool_dialog) > 6000 then\n                ensureSurgE()\n            end\n            if cfg.pathfind and not restocking and not provisioning then\n                local x, y = findSurgE()\n                if x and type(FindPath) == "function" then\n                    local p = type(GetLocal) == "function" and GetLocal() or nil\n                    if p then\n                        local px, py = math.floor((p.posX or 0)/32), math.floor((p.posY or 0)/32)\n                        -- Target the Surg-E tile itself, not the old x-1 adjacent tile.\n                        if math.abs(px-x) > 1 or math.abs(py-y) > 1 then\n                            if (nowms() - (last_path or 0)) > 2500 then\n                                last_path = nowms()\n                                FindPath(x, y)\n                            end\n                        else\n                            -- Next to the Surg-E: wrench it (not while a surgery is in progress).\n                            local t = nowms()\n                            if (t - last_tool_dialog) > 6000 and (t - last_wrench) > 3000 then\n                                last_wrench = t\n                                wrenchTile(x, y)\n                            end\n                        end\n                    end\n                end\n            end\n            Sleep(1000)\n        end\n    end)\nend\nzs_surgery_path_loop()\n'
  local z =
    '-- ==========================================================\n--                 AUTO SPLICE & PLANT (ZS)\n--   Uses the same Harvest Provider movement pattern:\n--   scan row-by-row, left-to-right, group up to 3 tiles,\n--   stand at the group, then plant/splice those 3 tiles.\n-- ==========================================================\nlocal farmRunning = false\nlocal farmStop = false\nlocal plantedAt = {}\nlocal WALK_DELAY = 250\nlocal CHECKPOINT_FILE = "zs_plant_splice_checkpoint.txt"\nlocal checkpointWorld = ""\nlocal checkpointMode = ""\n\n-- PowerKuy builds that expose Lua file I/O can persist progress across a\n-- disconnect/reload. If file I/O is unavailable, the script still rescans\n-- the world on the next manual start, but cannot promise timer-state recovery.\nlocal function saveCheckpoint()\n    if not io or type(io.open) ~= "function" then return false end\n    local f = io.open(CHECKPOINT_FILE, "w")\n    if not f then return false end\n    f:write("mode=", tostring(checkpointMode), "\\n")\n    f:write("world=", tostring(checkpointWorld), "\\n")\n    for key, stamp in pairs(plantedAt) do\n        f:write("seed=", tostring(key), "|", tostring(stamp), "\\n")\n    end\n    f:close()\n    return true\nend\n\nlocal function loadCheckpoint(mode)\n    if not io or type(io.open) ~= "function" then return false end\n    local f = io.open(CHECKPOINT_FILE, "r")\n    if not f then return false end\n    local loadedMode, loadedWorld, restored = "", "", {}\n    for line in f:lines() do\n        local m = line:match("^mode=(.*)$")\n        local w = line:match("^world=(.*)$")\n        local key, stamp = line:match("^seed=(.-)|([%d%.%-]+)$")\n        if m then loadedMode = m end\n        if w then loadedWorld = w end\n        if key and stamp then restored[key] = tonumber(stamp) or 0 end\n    end\n    f:close()\n    if loadedMode == mode then\n        plantedAt = restored\n        checkpointWorld = loadedWorld\n        checkpointMode = loadedMode\n        return true\n    end\n    return false\nend\n\nlocal function note(msg)\n    if growtopia and type(growtopia.notify) == "function" then\n        pcall(growtopia.notify, tostring(msg))\n    else\n        print("[ZS Auto Splice & Plant] " .. tostring(msg))\n    end\nend\n\nlocal function nowSec()\n    if type(os) == "table" and type(os.time) == "function" then\n        return os.time()\n    end\n    if type(getTime) == "function" then\n        return getTime()\n    end\n    return 0\nend\n\nlocal function readSeedPicker(alias)\n    local raw\n    pcall(function() raw = getValue(1, alias) end)\n\n    if type(raw) ~= "number" or raw <= 0 then\n        local str\n        pcall(function() str = getValue(2, alias) end)\n        if type(str) == "table" then\n            raw = tonumber(str.id or str.itemID or str.itemid or str.value)\n        else\n            raw = tonumber(str)\n        end\n        if not raw and type(str) == "string" and str:match("%S") then\n            local clean = str:match("^%s*(.-)%s*$")\n            if growtopia and type(growtopia.getItemID) == "function" then\n                local ok, id = pcall(growtopia.getItemID, clean)\n                if ok then raw = tonumber(id) end\n            end\n        end\n    end\n\n    if type(raw) ~= "number" or raw <= 0 then return nil end\n    raw = math.floor(raw)\n    -- A picked block ID becomes its seed ID; an odd seed ID stays unchanged.\n    if raw % 2 == 0 then raw = raw + 1 end\n    return raw\nend\n\nlocal function invCount(id)\n    if not growtopia or type(growtopia.checkInventoryCount) ~= "function" then\n        return 0\n    end\n    local ok, count = pcall(growtopia.checkInventoryCount, id)\n    if ok then return tonumber(count) or 0 end\n    return 0\nend\n\nlocal function getTileSafe(x, y)\n    if type(GetTile) ~= "function" then return nil end\n    local ok, tile = pcall(GetTile, x, y)\n    if ok then return tile end\n    return nil\nend\n\nlocal function tileFg(tile)\n    return tonumber(tile and tile.fg) or 0\nend\n\nlocal function getPlayer()\n    if type(GetLocal) ~= "function" then return nil end\n    local ok, player = pcall(GetLocal)\n    if ok then return player end\n    return nil\nend\n\nlocal function near(tx, ty)\n    local p = getPlayer()\n    if not p or not p.posX or not p.posY then return false end\n    return math.abs(p.posX / 32 - tx) <= 2\n       and math.abs(p.posY / 32 - ty) <= 2\nend\n\nlocal function placeItem(id, x, y)\n    local p = getPlayer()\n    if not p or type(SendPacketRaw) ~= "function" then return false end\n    local ok = pcall(SendPacketRaw, false, {\n        x = p.posX, y = p.posY,\n        px = x, py = y,\n        type = 3, value = id\n    })\n    return ok\nend\n\nlocal function isFreshSeed(x, y)\n    -- A saved seed may still need its second splice after a long disconnect.\n    -- Keep the marker until the tile changes to its completed hybrid ID.\n    return plantedAt[x .. "," .. y] ~= nil\nend\n\nlocal function hasSupport(x, y)\n    local below = getTileSafe(x, y + 1)\n    local fg = tileFg(below)\n    return fg > 0 and fg ~= 6 and fg % 2 == 0\nend\n\nlocal function tileStatus(t, seed1, seed2, useSplice)\n    if not t or not t.x or not t.y then return nil end\n    local x, y = tonumber(t.x), tonumber(t.y)\n    if not x or not y or not hasSupport(x, y) then return nil end\n\n    local currentTile = getTileSafe(x, y)\n    if not currentTile then return nil end\n    local fg = tileFg(currentTile)\n    if fg == 0 then return "EMPTY" end\n\n    if useSplice and isFreshSeed(x, y) then\n        if fg == seed1 then return "NEEDS_SPLICE_2" end\n        if fg == seed2 then return "NEEDS_SPLICE_1" end\n    end\n    return nil\nend\n\nlocal function walkable(x, y)\n    local fg = tileFg(getTileSafe(x, y))\n    return fg == 0 or fg % 2 == 1\nend\n\n-- Row order is top-to-bottom and left-to-right.\n-- Each group covers no more than three adjacent tiles.\nlocal function makeGroups(list)\n    table.sort(list, function(a, b)\n        if a.y == b.y then return a.x < b.x end\n        return a.y < b.y\n    end)\n\n    local groups, i = {}, 1\n    while i <= #list do\n        local first = list[i]\n        local group = { first }\n        local j = i + 1\n        while j <= #list\n          and list[j].y == first.y\n          and list[j].x <= first.x + 2 do\n            group[#group + 1] = list[j]\n            j = j + 1\n        end\n        groups[#groups + 1] = group\n        i = j\n    end\n    return groups\nend\n\nlocal function scanPlantable(seed1, seed2, useSplice, skip)\n    local tiles = {}\n    if type(GetTiles) ~= "function" then return tiles end\n\n    local ok, worldTiles = pcall(GetTiles)\n    if not ok or type(worldTiles) ~= "table" then return tiles end\n\n    for _, tile in pairs(worldTiles) do\n        local x, y = tonumber(tile and tile.x), tonumber(tile and tile.y)\n        if x and y then\n            local candidate = { x = math.floor(x), y = math.floor(y) }\n            local key = candidate.x .. "," .. candidate.y\n            if (skip[key] or 0) < 3\n              and tileStatus(candidate, seed1, seed2, useSplice) then\n                tiles[#tiles + 1] = candidate\n            end\n        end\n    end\n    return makeGroups(tiles)\nend\n\n-- Same stop position as Harvest Provider: stand near the middle of each\n-- 3-tile group, then work across the group before moving to the next one.\nlocal function goStand(group)\n    local first = group[1]\n    local sx, sy = first.x + 1, first.y\n    if not walkable(sx, sy) then sx = first.x end\n    if type(FindPath) == "function" then\n        pcall(FindPath, sx, sy)\n    end\n    Sleep(WALK_DELAY)\nend\n\nlocal function isComplete(tile, seed1, seed2, useSplice)\n    local fg = tileFg(getTileSafe(tile.x, tile.y))\n    if fg == 0 then return false end\n    if useSplice and isFreshSeed(tile.x, tile.y)\n      and (fg == seed1 or fg == seed2) then\n        return false\n    end\n    return true\nend\n\nlocal function plantOrSpliceTile(tile, seed1, seed2, useSplice, plantDelay, spliceDelay)\n    local status = tileStatus(tile, seed1, seed2, useSplice)\n    if not status then return true end\n\n    if status == "EMPTY" then\n        if invCount(seed1) <= 0 then return false, "noseed1" end\n        if useSplice and invCount(seed2) <= 0 then return false, "noseed2" end\n        if not placeItem(seed1, tile.x, tile.y) then return false, "packet" end\n        plantedAt[tile.x .. "," .. tile.y] = nowSec()\n        saveCheckpoint()\n        Sleep(plantDelay)\n        status = useSplice and "NEEDS_SPLICE_2" or nil\n    elseif status == "NEEDS_SPLICE_1" then\n        if invCount(seed1) <= 0 then return false, "noseed1" end\n        if not placeItem(seed1, tile.x, tile.y) then return false, "packet" end\n        Sleep(plantDelay)\n        status = nil\n    end\n\n    if useSplice and status == "NEEDS_SPLICE_2" then\n        if invCount(seed2) <= 0 then return false, "noseed2" end\n        Sleep(spliceDelay)\n        if not placeItem(seed2, tile.x, tile.y) then return false, "packet" end\n        saveCheckpoint()\n        Sleep(plantDelay)\n    end\n\n    return true\nend\n\nlocal function bump(skip, tile)\n    local key = tile.x .. "," .. tile.y\n    skip[key] = (skip[key] or 0) + 1\nend\n\nlocal function plantGroup(group, seed1, seed2, useSplice, plantDelay, spliceDelay, skip)\n    local pending = {}\n    for _, tile in ipairs(group) do\n        if not isComplete(tile, seed1, seed2, useSplice) then\n            pending[#pending + 1] = tile\n        end\n    end\n\n    local done, completed = 0, {}\n    -- Keep working on this same group until every target tile is confirmed\n    -- planted/spliced, or the user explicitly turns the feature OFF.\n    while #pending > 0 and not farmStop do\n        goStand(group)\n        Sleep(WALK_DELAY)\n\n        local nextPending = {}\n        for _, tile in ipairs(pending) do\n            if farmStop then return done, "stop" end\n\n            if not near(tile.x, tile.y) then\n                -- Try a reachable standing tile beside the target, then retry.\n                local sx, sy = tile.x + 1, tile.y\n                if not walkable(sx, sy) then sx = tile.x - 1 end\n                if type(FindPath) == "function" then pcall(FindPath, sx, sy) end\n                Sleep(WALK_DELAY * 2)\n            end\n\n            if not isComplete(tile, seed1, seed2, useSplice) then\n                local ok, reason = plantOrSpliceTile(\n                    tile, seed1, seed2, useSplice, plantDelay, spliceDelay\n                )\n                if not ok then\n                    if reason == "noseed1" or reason == "noseed2" then\n                        return done, reason\n                    end\n                    -- A transient packet/API failure is retried on this tile.\n                    nextPending[#nextPending + 1] = tile\n                else\n                    -- Give the game/server time to update the tile, then verify.\n                    Sleep(math.max(plantDelay, 250))\n                    if not isComplete(tile, seed1, seed2, useSplice) then\n                        nextPending[#nextPending + 1] = tile\n                    elseif not completed[tile.x .. "," .. tile.y] then\n                        completed[tile.x .. "," .. tile.y] = true\n                        done = done + 1\n                    end\n                end\n            elseif not completed[tile.x .. "," .. tile.y] then\n                completed[tile.x .. "," .. tile.y] = true\n                done = done + 1\n            end\n        end\n\n        pending = nextPending\n        saveCheckpoint()\n        if #pending > 0 and not farmStop then Sleep(500) end\n    end\n\n    if farmStop then return done, "stop" end\n    return done\nend\n\nlocal function getSeedStorageObjects()\n    local objects\n    if type(GetObjects) == "function" then\n        local ok, result = pcall(GetObjects)\n        if ok and type(result) == "table" then objects = result end\n    end\n    if not objects and type(GetObjectList) == "function" then\n        local ok, result = pcall(GetObjectList)\n        if ok and type(result) == "table" then objects = result end\n    end\n    return objects or {}\nend\n\nlocal function seedObjectID(obj)\n    return tonumber(obj and (obj.itemid or obj.itemID or obj.item_id))\nend\n\nlocal function seedObjectPosition(obj)\n    if not obj then return nil, nil end\n    local pos = obj.pos or obj.position\n    local x = (pos and (pos.x or pos.posX)) or obj.x or obj.posX\n    local y = (pos and (pos.y or pos.posY)) or obj.y or obj.posY\n    return tonumber(x), tonumber(y)\nend\n\nlocal function waitForSeedWorld(worldName, timeout)\n    local waited = 0\n    while waited < timeout do\n        if type(GetWorldName) == "function" and GetWorldName():upper() == worldName:upper() then\n            return true\n        end\n        Sleep(250)\n        waited = waited + 250\n    end\n    return type(GetWorldName) == "function" and GetWorldName():upper() == worldName:upper()\nend\n\nlocal function collectSeedDrops(seedID, targetAmount)\n    local before = invCount(seedID)\n    if before >= targetAmount then return true end\n    local objects = {}\n    for _, obj in pairs(getSeedStorageObjects()) do\n        local ox, oy = seedObjectPosition(obj)\n        if seedObjectID(obj) == seedID and ox and oy then\n            objects[#objects + 1] = {\n                x = math.floor(ox / 32), y = math.floor(oy / 32),\n                px = ox, py = oy\n            }\n        end\n    end\n    table.sort(objects, function(a, b)\n        if a.y == b.y then return a.x < b.x end\n        return a.y < b.y\n    end)\n\n    for _, obj in ipairs(objects) do\n        if farmStop then return false end\n        if invCount(seedID) >= targetAmount then break end\n        FindPath(obj.x, obj.y)\n        Sleep(WALK_DELAY + 150)\n        -- Refresh inventory after the normal world-drop pickup has had time to run.\n        Sleep(250)\n    end\n    return invCount(seedID) > before\nend\n\n-- Restocks loose seed drops from the configured storage world, then returns\n-- to the exact farm world/tile so the current row can continue.\nlocal function restockSeeds(seed1, seed2, useSplice)\n    local storageWorld = getValue(2, "zs_ap_storage_world")\n    storageWorld = tostring(storageWorld or ""):match("^%s*(.-)%s*$")\n    if storageWorld == "" then\n        note("Seed inventory is empty. Enter a Storage World first.")\n        return false, "nostorage"\n    end\n    if not growtopia or type(growtopia.warpTo) ~= "function" then\n        note("Cannot restock: warp API is unavailable.")\n        return false, "storagefail"\n    end\n\n    local farmWorld = GetWorldName()\n    local player = getPlayer()\n    local returnX = player and math.floor((player.posX or 0) / 32) or nil\n    local returnY = player and math.floor((player.posY or 0) / 32) or nil\n    if not farmWorld or farmWorld == "EXIT" then\n        return false, "storagefail"\n    end\n\n    note("Seed stock low. Going to Storage World: " .. storageWorld .. "...")\n    if farmWorld:upper() ~= storageWorld:upper() then\n        growtopia.warpTo(storageWorld)\n        if not waitForSeedWorld(storageWorld, 15000) then\n            note("Could not enter Storage World: " .. storageWorld)\n            return false, "storagefail"\n        end\n    end\n    Sleep(800)\n\n    collectSeedDrops(seed1, 200)\n    if useSplice then collectSeedDrops(seed2, 200) end\n\n    local count1 = invCount(seed1)\n    local count2 = useSplice and invCount(seed2) or 200\n    local canContinue = count1 > 0 and (not useSplice or count2 > 0)\n\n    if farmWorld:upper() ~= storageWorld:upper() then\n        growtopia.warpTo(farmWorld)\n        if not waitForSeedWorld(farmWorld, 15000) then\n            note("Seeds collected, but could not return to farm world: " .. farmWorld)\n            return false, "returnfail"\n        end\n    end\n    if returnX and returnY then\n        FindPath(returnX, returnY)\n        Sleep(WALK_DELAY)\n    end\n\n    if canContinue then\n        note("Restock complete. Seed 1: " .. count1 .. (useSplice and (" | Seed 2: " .. count2) or "") .. ". Continuing...")\n        return true\n    end\n\n    note("Storage World does not have enough loose seeds. Seed 1: " .. count1 .. (useSplice and (" | Seed 2: " .. count2) or "") .. ".")\n    return false, "storageempty"\nend\n\nlocal function plantWorld(seed1, seed2, useSplice, plantDelay, spliceDelay)\n    local total = 0\n    checkpointWorld = type(GetWorldName) == "function" and GetWorldName() or ""\n    saveCheckpoint()\n\n    -- Work one complete horizontal row at a time. Finish every group on the\n    -- row, rescan that same row for missed/empty targets, and only then move\n    -- down to the next row.\n    local rowYs = {}\n    local function refreshRows()\n        local seen = {}\n        if type(GetTiles) ~= "function" then return end\n        local ok, worldTiles = pcall(GetTiles)\n        if not ok or type(worldTiles) ~= "table" then return end\n        for _, tile in pairs(worldTiles) do\n            local y = tonumber(tile and tile.y)\n            if y then\n                y = math.floor(y)\n                if not seen[y] then seen[y] = true; rowYs[#rowYs + 1] = y end\n            end\n        end\n        table.sort(rowYs)\n    end\n    refreshRows()\n\n    for _, rowY in ipairs(rowYs) do\n        if farmStop then return total, "stop" end\n\n        local rowPass = 0\n        while not farmStop do\n            rowPass = rowPass + 1\n            local pending = {}\n            if type(GetTiles) == "function" then\n                local ok, worldTiles = pcall(GetTiles)\n                if ok and type(worldTiles) == "table" then\n                    for _, tile in pairs(worldTiles) do\n                        local x, y = tonumber(tile and tile.x), tonumber(tile and tile.y)\n                        if x and y and math.floor(y) == rowY then\n                            local candidate = {x = math.floor(x), y = rowY}\n                            if tileStatus(candidate, seed1, seed2, useSplice) then\n                                pending[#pending + 1] = candidate\n                            end\n                        end\n                    end\n                end\n            end\n\n            if #pending == 0 then\n                note("Row " .. tostring(rowY) .. " verified: no missed planting/splicing spots.")\n                break\n            end\n\n            local groups = makeGroups(pending)\n            local madeProgress = false\n            for _, group in ipairs(groups) do\n                if farmStop then return total, "stop" end\n\n                if invCount(seed1) <= 0 or (useSplice and invCount(seed2) <= 0) then\n                    local stocked, stockReason = restockSeeds(seed1, seed2, useSplice)\n                    if not stocked then return total, stockReason end\n                end\n\n                goStand(group)\n                local planted, reason = plantGroup(\n                    group, seed1, seed2, useSplice, plantDelay, spliceDelay, {}\n                )\n                saveCheckpoint()\n                total = total + (planted or 0)\n                if (planted or 0) > 0 then madeProgress = true end\n\n                if reason == "stop" then\n                    return total, "stop"\n                elseif reason == "noseed1" or reason == "noseed2" then\n                    local stocked, stockReason = restockSeeds(seed1, seed2, useSplice)\n                    if not stocked then return total, stockReason end\n                    local retryDone, retryReason = plantGroup(\n                        group, seed1, seed2, useSplice, plantDelay, spliceDelay, {}\n                    )\n                    total = total + (retryDone or 0)\n                    if (retryDone or 0) > 0 then madeProgress = true end\n                    if retryReason then return total, retryReason end\n                elseif reason then\n                    return total, reason\n                end\n            end\n\n            -- Always rescan the current row, even if the previous pass appeared\n            -- successful. If no tile status changed, wait and retry rather than\n            -- advancing to another row with a hole left behind.\n            Sleep(400)\n            local stillPending = {}\n            local ok, worldTiles = pcall(GetTiles)\n            if ok and type(worldTiles) == "table" then\n                for _, tile in pairs(worldTiles) do\n                    local x, y = tonumber(tile and tile.x), tonumber(tile and tile.y)\n                    if x and y and math.floor(y) == rowY then\n                        local candidate = {x = math.floor(x), y = rowY}\n                        if tileStatus(candidate, seed1, seed2, useSplice) then\n                            stillPending[#stillPending + 1] = candidate\n                        end\n                    end\n                end\n            end\n            if #stillPending == 0 then\n                note("Row " .. tostring(rowY) .. " complete and verified.")\n                break\n            end\n            if not madeProgress then\n                note("Still checking row " .. tostring(rowY) .. ": retrying " .. tostring(#stillPending) .. " unfinished spots.")\n                Sleep(700)\n            end\n        end\n    end\n\n    if farmStop then return total, "stop" end\n    return total, "done"\nend\n\nlocal function parseFarmWorlds(raw)\n    local worlds, seen = {}, {}\n    raw = tostring(raw or "")\n    for name in raw:gmatch("[^,;\\n]+") do\n        name = name:match("^%s*(.-)%s*$")\n        if name ~= "" then\n            local key = name:upper()\n            if not seen[key] then\n                seen[key] = true\n                worlds[#worlds + 1] = name\n            end\n        end\n    end\n    return worlds\nend\n\nlocal function farmWorlds(seed1, seed2, useSplice, plantDelay, spliceDelay)\n    local raw = getValue(2, "zs_ap_worlds")\n    local worlds = parseFarmWorlds(raw)\n    if #worlds == 0 then\n        local current = type(GetWorldName) == "function" and GetWorldName() or nil\n        if current and current ~= "EXIT" then worlds[1] = current end\n    end\n    if #worlds == 0 then return 0, "noworld" end\n    if not growtopia or type(growtopia.warpTo) ~= "function" then\n        return 0, "worldwarp"\n    end\n\n    local total = 0\n    for _, world in ipairs(worlds) do\n        if farmStop then return total, "stop" end\n        local current = type(GetWorldName) == "function" and GetWorldName() or ""\n        if current:upper() ~= world:upper() then\n            note("Going to farm world: " .. world)\n            growtopia.warpTo(world)\n            if not waitForSeedWorld(world, 15000) then\n                note("Could not enter farm world: " .. world)\n                return total, "worldwarp"\n            end\n            Sleep(700)\n        end\n        checkpointWorld = world\n        checkpointMode = useSplice and "splice" or "plant"\n        saveCheckpoint()\n        local count, reason = plantWorld(seed1, seed2, useSplice, plantDelay, spliceDelay)\n        total = total + (count or 0)\n        if reason ~= "done" then return total, reason end\n    end\n    return total, "done"\nend\n\nlocal function farmRun(useSplice)\n    local seed1Key = useSplice and "zs_as_seed1" or "zs_ap_seed1"\n    local seed2Key = "zs_as_seed2"\n    local seed1 = readSeedPicker(seed1Key)\n    local seed2 = useSplice and readSeedPicker(seed2Key) or nil\n    if not seed1 then\n        note(useSplice and "Choose Seed 1 in ZS Auto Splice first." or "Choose a seed in Auto Plant first.")\n        farmRunning = false\n        return\n    end\n\n    if useSplice and (not seed2 or seed2 <= 0) then\n        note("Choose Seed 2 in ZS Auto Splice first.")\n        farmRunning = false\n        return\n    end\n    if useSplice and seed1 == seed2 then\n        note("Seed 1 and Seed 2 must be different.")\n        farmRunning = false\n        return\n    end\n\n    if not getPlayer() then\n        note("Player data is not available.")\n        farmRunning = false\n        return\n    end\n\n    local plantDelay = tonumber(getValue(2, "zs_ap_delay")) or 190\n    local spliceDelay = tonumber(getValue(2, "zs_ap_splice_delay")) or 200\n    plantDelay = math.max(60, math.min(1000, math.floor(plantDelay)))\n    spliceDelay = math.max(100, math.min(1000, math.floor(spliceDelay)))\n\n    local modeName = useSplice and "splice" or "plant"\n    local resumed = loadCheckpoint(modeName)\n    checkpointMode = modeName\n    farmStop = false\n\n    if resumed then\n        note("Recovery data loaded. Rechecking farm worlds and unfinished seed/splice spots before continuing.")\n    else\n        plantedAt = {}\n        note("New run started. Progress checkpoint will be saved when Lua file access is available.")\n    end\n    saveCheckpoint()\n    note("Auto Splice & Plant started. Working left-to-right in groups of 3; each group is verified before moving on.")\n    local total, reason = farmWorlds(seed1, seed2, useSplice, plantDelay, spliceDelay)\n\n    farmRunning = false\n    if reason == "done" then\n        note("Finished. Planted/spliced " .. tostring(total) .. " tiles.")\n    elseif reason == "noseed1" then\n        note("Stopped: Seed 1 is empty. Planted/spliced " .. tostring(total) .. " tiles.")\n    elseif reason == "noseed2" then\n        note("Stopped: Seed 2 is empty. Planted " .. tostring(total) .. " tiles; some may still need splicing.")\n    elseif reason == "nostorage" or reason == "storagefail" or reason == "storageempty" or reason == "returnfail" then\n        note("Stopped: automatic seed restock failed. Completed " .. tostring(total) .. " tiles.")\n    elseif reason == "blocked" then\n        note("Stopped: some tiles could not be reached. Completed " .. tostring(total) .. " tiles.")\n    elseif reason == "noworld" or reason == "worldwarp" then\n        note("Stopped: farm world list is empty or a world could not be entered. Completed " .. tostring(total) .. " tiles.")\n    else\n        note("Stopped. Completed " .. tostring(total) .. " tiles.")\n    end\nend\n\n-- AUTO PLANT: one selected seed, no splice step.\nlocal ap = UserInterface.new("ZS AUTO PLANT", "Park")\nap:addLabelApp("* ZS AUTO PLANT *", "Park")\nap:addTooltip("* AUTO PLANT *", "Select one seed, add farm worlds and a Storage World.\\nThe script plants left-to-right in groups of 3 and restocks up to 200 seeds.\\nToggle AUTO PLANT ON/OFF to start or stop.", "Info", true)\nap:addDivider()\nap:addItemPicker("Item To Farm", "Blank", "", "zs_ap_seed1")\nap:addInputString("Worlds to Plant", "", "Worlds to Plant", "Enter worlds separated by commas; blank = current world", "Worlds", "zs_ap_worlds")\nap:addInputString("Storage World", "", "Storage World", "Enter the world where loose seeds are stored", "World", "zs_ap_storage_world")\nap:addSlider("Plant Delay (ms)", 60, 1000, 190, 10, false, "zs_ap_delay")\nap:addDivider()\nap:addToggle("AUTO PLANT", false, "zs_ap_run", true)\naddIntoModule(ap:generateJSON(), "ZS")\n\n-- ZS AUTO SPLICE: two selected seeds, splice enabled by design.\nlocal as = UserInterface.new("ZS AUTO SPLICE", "Park")\nas:addLabelApp("* ZS AUTO SPLICE *", "Park")\nas:addTooltip("* AUTO SPLICE *", "Choose both Items To Farm, add farm worlds and a Storage World.\\nThe script plants/splices left-to-right in groups of 3 and restocks up to 200 of each seed.\\nToggle AUTO SPLICE ON/OFF to start or stop.", "Info", true)\nas:addDivider()\nas:addItemPicker("Item To Farm", "Blank", "", "zs_as_seed1")\nas:addItemPicker("Item To Farm", "Blank", "", "zs_as_seed2")\nas:addInputString("Worlds to Splice", "", "Worlds to Splice", "Enter worlds separated by commas; blank = current world", "Worlds", "zs_ap_worlds")\nas:addInputString("Storage World", "", "Storage World", "Enter the world where loose seeds are stored", "World", "zs_ap_storage_world")\nas:addSlider("Plant Delay (ms)", 60, 1000, 190, 10, false, "zs_ap_delay")\nas:addSlider("Splice Delay (ms)", 100, 1000, 200, 10, false, "zs_ap_splice_delay")\nas:addDivider()\nas:addToggle("AUTO SPLICE", false, "zs_as_run", true)\naddIntoModule(as:generateJSON(), "ZS")\n\naddHook(function(evType, name, value)\n    if name == "zs_ap_run" or name == "zs_as_run" then\n        local spliceMode = name == "zs_as_run"\n        if value then\n            if farmRunning then\n                note("A planting task is already running.")\n                return\n            end\n            farmRunning = true\n            farmStop = false\n            ZS_thread(function() farmRun(spliceMode) end)\n        else\n            farmStop = true\n            note((spliceMode and "AUTO SPLICE" or "AUTO PLANT") .. ": OFF. Current position will be kept.")\n        end\n    end\nend, "onValue")\n\n'
