  local h =
    '-- =========================================================================\n--  ZS | Gaia\'s Beacon / Unstable Tesseract  -  Auto Retrieve & Drop\n--  Recovery patch: nil-safe local-player and OnVariant handling\n--  Script Created By ZS\n--  Growlauncher (PowerKuy) Lua script\n-- =========================================================================\n\nlocal json  = require("json")\nlocal pref  = require("preferences")\nlocal saved = pref:new("zs_gaut_auto_retrieve.json")\n\n-- -------------------------------------------------------------------------\n--  Config\n-- -------------------------------------------------------------------------\nlocal CFG = {\n    title        = "ZS AUTO GAUT",\n    author       = "ZS",\n    category     = "ZS",       -- mod menu tab\n    categoryIcon = "Shield",\n    loadDelay    = 6000,         -- ms before the module is added to the menu\n    maxTake      = 200,          -- max items per retrieve\n    wrenchWait   = 700,          -- ms to wait for the machine dialog (in range)\n    wrenchWaitFar= 1500,         -- ms to wait after walking to the machine\n    idleWait     = 2000,         -- ms between scans when every machine is empty\n}\n\nlocal MACHINES = {\n    gaia = { id = 6946, dialog = "itemsucker_seed",  name = "Gaia\'s Beacon" },\n    ut   = { id = 6948, dialog = "itemsucker_block", name = "Unstable Tesseract" },\n}\n\n-- -------------------------------------------------------------------------\n--  State\n-- -------------------------------------------------------------------------\nlocal S = {\n    running   = false,\n    token     = 0,\n    kind      = saved:get("kind", "gaia"),\n    delay     = saved:get("delay", 150),\n    dropX     = saved:get("drop_x", nil),\n    dropY     = saved:get("drop_y", nil),\n    dropWorld = saved:get("drop_world", nil),\n    waiting   = false,   -- true while we expect a machine dialog (so it gets hidden)\n    info      = nil,     -- last parsed machine dialog\n    state     = "Stopped",\n    machine   = "-",\n    total     = 0,\n}\n\n-- -------------------------------------------------------------------------\n--  Helpers\n-- -------------------------------------------------------------------------\nlocal function say(msg)\n    pcall(log, "[ZS] " .. tostring(msg))\nend\n\nlocal function notify(msg)\n    pcall(sendNotification, tostring(msg))\n    say(msg)\nend\n\nlocal function myTile()\n    if type(getLocal) ~= "function" then return nil, nil end\n    local ok, me = pcall(getLocal)\n    if not ok or type(me) ~= "table" or type(me.posX) ~= "number" or type(me.posY) ~= "number" then\n        return nil, nil\n    end\n    return math.floor(me.posX / 32), math.floor(me.posY / 32)\nend\n\nlocal function updateStatus()\n    local list = {\n        { "State",     S.state },\n        { "Source",    "Gaia + Unstable Tesseract" },\n        { "Machine",   S.machine },\n        { "Drop Pos",  S.dropX and (S.dropX .. ", " .. S.dropY) or "Not set" },\n        { "Retrieved", tostring(S.total) },\n    }\n    pcall(editValue, "zs_gaut_status", json:encode(list))\nend\n\nlocal function alive(token)\n    return S.running and S.token == token\nend\n\n-- sleep that wakes up early when the script is stopped\nlocal function wait(ms, token)\n    local t = 0\n    while t < ms and alive(token) do\n        sleep(25)\n        t = t + 25\n    end\nend\n\n-- -------------------------------------------------------------------------\n--  Packets (same protocol the game uses)\n-- -------------------------------------------------------------------------\nlocal function gap()\n    sleep(math.max(S.delay, 100))\nend\n\nlocal function wrenchTile(x, y)\n    if type(getLocal) ~= "function" or type(sendPacketRaw) ~= "function" then return false end\n    local ok, p = pcall(getLocal)\n    if not ok or type(p) ~= "table" or type(p.posX) ~= "number" or type(p.posY) ~= "number" then return false end\n    sendPacketRaw(false, {\n        type = 3, value = 32,\n        px = x, py = y,\n        x = p.posX, y = p.posY,\n    })\n    return true\nend\n\nlocal function sendRetrieve(dialog, x, y, amount)\n    sendPacket(2, table.concat({\n        "action|dialog_return",\n        "dialog_name|" .. dialog,\n        "tilex|" .. x .. "|",\n        "tiley|" .. y .. "|",\n        "buttonClicked|retrieveitem",\n        "",\n        "chk_enablesucking|1",\n        ""\n    }, "\\n"))\n\n    gap()\n\n    sendPacket(2, table.concat({\n        "action|dialog_return",\n        "dialog_name|itemremovedfromsucker",\n        "tilex|" .. x .. "|",\n        "tiley|" .. y .. "|",\n        "itemtoremove|" .. amount,\n        ""\n    }, "\\n"))\nend\n\nlocal function dropItem(id, amount)\n    sendPacket(2, "action|drop\\nitemID|" .. id)\n    gap()\n    sendPacket(2, "action|dialog_return\\ndialog_name|drop_item\\nitemID|" .. id .. "|\\ncount|" .. amount .. "\\n")\nend\n\n-- -------------------------------------------------------------------------\n--  Inventory\n-- -------------------------------------------------------------------------\nlocal function invCount(id)\n    local ok, inv = pcall(getInventory)\n    if not ok or type(inv) ~= "table" then return 0 end\n    for _, it in pairs(inv) do\n        if it.id == id then return it.amount or 0 end\n    end\n    return 0\nend\n\nlocal function waitGain(id, before, token)\n    local t = 0\n    while t < 1800 and alive(token) do\n        sleep(50)\n        t = t + 50\n        local now = invCount(id)\n        if now > before then\n            sleep(80)\n            return invCount(id) - before\n        end\n    end\n    return 0\nend\n\nlocal function waitInvAtMost(id, limit, token)\n    local t = 0\n    while t < 1500 and alive(token) do\n        if invCount(id) <= limit then return end\n        sleep(50)\n        t = t + 50\n    end\nend\n\n-- -------------------------------------------------------------------------\n--  Movement\n-- -------------------------------------------------------------------------\nlocal function path(x, y)\n    -- PowerKuy builds expose either FindPath or findPath. A successful pcall\n    -- alone is not enough: reject missing APIs and explicit false returns.\n    -- Do not wrap FindPath in pcall: some PowerKuy builds yield while pathing,\n    -- and pcall can interrupt that yield, producing "Path not found".\n    if type(FindPath) == "function" then\n        local result = FindPath(x, y)\n        return result ~= false\n    end\n    if type(findPath) == "function" then\n        local result = findPath(x, y)\n        return result ~= false\n    end\n    return false\nend\n\nlocal function moveTo(x, y, token)\n    if type(x) ~= "number" or type(y) ~= "number" then return false end\n    local cx, cy = myTile()\n    if cx == x and cy == y then return true end\n    if not path(x, y) then return false end\n    local t = 0\n    while t < 4000 and alive(token) do\n        sleep(50)\n        t = t + 50\n        cx, cy = myTile()\n        if cx == x and cy == y then return true end\n    end\n    return false\nend\n\nlocal function withinWrenchReach(x, y)\n    local px, py = myTile()\n    if px == nil or py == nil then return false end\n    -- Wrench range is treated as a two-tile square around the machine.\n    return math.abs(px - x) <= 2 and math.abs(py - y) <= 2\nend\n\nlocal function moveNearMachine(x, y, token)\n    -- Walk toward the nearest reachable tile around the machine. Never ask\n    -- FindPath to the machine tile itself: it may be occupied or enclosed.\n    if withinWrenchReach(x, y) then return true end\n    local candidates = {}\n    for radius = 1, 3 do\n        for dx = -radius, radius do\n            for dy = -radius, radius do\n                if math.max(math.abs(dx), math.abs(dy)) == radius then\n                    candidates[#candidates + 1] = { x + dx, y + dy, radius }\n                end\n            end\n        end\n    end\n    -- Prefer the closest candidate to the current player position.\n    local px, py = myTile()\n    table.sort(candidates, function(a, b)\n        local da = math.abs(a[1] - (px or a[1])) + math.abs(a[2] - (py or a[2]))\n        local db = math.abs(b[1] - (px or b[1])) + math.abs(b[2] - (py or b[2]))\n        if da == db then return a[3] < b[3] end\n        return da < db\n    end)\n    local attempts = 0\n    for _, target in ipairs(candidates) do\n        if not alive(token) then return false end\n        attempts = attempts + 1\n        if attempts > 18 then break end\n        -- FindPath can return nil on PowerKuy even when it starts walking.\n        -- Confirm by observing the player\'s actual tile, not its return.\n        local accepted = path(target[1], target[2])\n        if accepted then\n            local elapsed = 0\n            while elapsed < 1800 and alive(token) do\n                if withinWrenchReach(x, y) then return true end\n                sleep(100)\n                elapsed = elapsed + 100\n            end\n            if withinWrenchReach(x, y) then return true end\n        end\n    end\n    return withinWrenchReach(x, y)\nend\n\n-- -------------------------------------------------------------------------\n--  Finding machines\n-- -------------------------------------------------------------------------\nlocal function scanMachines()\n    local mx, my = myTile()\n    if mx == nil or my == nil then return {} end\n    local list, seen = {}, 0\n    local wanted = {\n        [MACHINES.gaia.id] = "gaia",\n        [MACHINES.ut.id] = "ut",\n    }\n\n    local ok, tiles = pcall(getTiles)\n    if ok and type(tiles) == "table" then\n        for _, t in pairs(tiles) do\n            seen = seen + 1\n            local kind = wanted[tonumber(t.fg)]\n            if kind then\n                list[#list + 1] = {\n                    x = tonumber(t.x), y = tonumber(t.y), kind = kind,\n                    d = math.abs(t.x - mx) + math.abs(t.y - my)\n                }\n            end\n        end\n    end\n\n    if seen == 0 then\n        for x = 0, 99 do\n            for y = 0, 59 do\n                local ok2, tile = pcall(getTile, x, y)\n                local kind = ok2 and type(tile) == "table" and wanted[tonumber(tile.fg)]\n                if kind then\n                    list[#list + 1] = { x=x, y=y, kind=kind, d=math.abs(x-mx)+math.abs(y-my) }\n                end\n            end\n        end\n    end\n\n    table.sort(list, function(a, b) return a.d < b.d end)\n    return list\nend\n\n-- -------------------------------------------------------------------------\n--  Dialog reading (wrench the machine, read how much it holds)\n-- -------------------------------------------------------------------------\nlocal function parseMachineDialog(text)\n    local def, kind\n    for key, candidate in pairs(MACHINES) do\n        if text:find(candidate.dialog, 1, true) and text:find("|" .. candidate.id .. "|", 1, true) then\n            def, kind = candidate, key\n            break\n        end\n    end\n    if not def then return nil end\n\n    local x    = text:match("embed_data|tilex|(%d+)")\n    local y    = text:match("embed_data|tiley|(%d+)")\n    local isi  = text:match("contains (%d+)")\n    local item = text:match("add_label_with_icon|small|[^|]*|left|(%d+)|")\n    if x and y and isi and item then\n        return {\n            dialog = def.dialog,\n            kind = kind,\n            x = tonumber(x), y = tonumber(y),\n            amount = tonumber(isi), item = tonumber(item),\n        }\n    end\n    return nil\nend\n\nlocal function wrenchRead(m, timeout, token)\n    S.info = nil\n    S.waiting = true\n    wrenchTile(m.x, m.y)\n\n    local t = 0\n    while t < timeout and not S.info and alive(token) do\n        sleep(25)\n        t = t + 25\n    end\n    S.waiting = false\n    return S.info\nend\n\n-- -------------------------------------------------------------------------\n--  Main work\n-- -------------------------------------------------------------------------\n\n-- Returns "worked", "empty" or "skip"\nlocal stopFlag = nil\n\nlocal function processMachine(m, token)\n    local worked = false\n    local retries = 0\n    S.machine = MACHINES[m.kind].name .. " (" .. m.x .. ", " .. m.y .. ")"\n\n    while alive(token) do\n        -- 1) If Gaia/UT is out of wrench range, FindPath toward nearby\n        -- approach tiles until the player is as close as possible. The\n        -- machine tile itself is never used as a path destination.\n        if not withinWrenchReach(m.x, m.y) then\n            S.state = "Walking near " .. MACHINES[m.kind].name\n            updateStatus()\n            moveNearMachine(m.x, m.y, token)\n        end\n        -- 2) Wrench the exact machine tile from the closest reachable spot.\n        local info = wrenchRead(m, CFG.wrenchWaitFar, token)\n        if not info and alive(token) then\n            sleep(250)\n            info = wrenchRead(m, CFG.wrenchWaitFar + 500, token)\n        end\n        if not info and alive(token) then\n            sleep(500)\n            info = wrenchRead(m, CFG.wrenchWaitFar + 1000, token)\n        end\n\n        if not info then\n            say("Could not open " .. MACHINES[m.kind].name .. " dialog after pathing to the nearest reachable tile. Check walls, range, or machine ID.")\n            return worked and "worked" or "skip"\n        end\n        if info.amount <= 0 then return worked and "worked" or "empty" end\n\n        -- 2) retrieve\n        local take   = math.min(info.amount, CFG.maxTake)\n        local before = invCount(info.item)\n        sendRetrieve(info.dialog, info.x, info.y, take)\n        local got = waitGain(info.item, before, token)\n\n        if got <= 0 then\n            retries = retries + 1\n            if retries >= 3 then\n                say("Items not entering inventory (full backpack?)")\n                return worked and "worked" or "skip"\n            end\n        else\n            retries = 0\n\n            -- 3) go to the saved drop position and drop\n            if not moveTo(S.dropX, S.dropY, token) then\n                say("Could not reach the drop position")\n            end\n            dropItem(info.item, got)\n            waitInvAtMost(info.item, before, token)\n\n            if invCount(info.item) > before then\n                S.dropFails = (S.dropFails or 0) + 1\n                if S.dropFails >= 2 then\n                    stopFlag = "Drop was blocked or failed - stopped."\n                    return worked and "worked" or "skip"\n                end\n            else\n                S.dropFails = 0\n            end\n\n            S.total = S.total + got\n            worked = true\n            updateStatus()\n        end\n\n        wait(math.max(S.delay, 100), token)\n    end\n    return worked and "worked" or "skip"\nend\n\nlocal function mainLoop(token)\n    while alive(token) do\n        if type(GetWorldName) ~= "function" or GetWorldName() ~= S.dropWorld then\n            S.state = "Stopped"\n            S.running = false\n            notify("World changed - set the drop position again.")\n            pcall(editToggle, "zs_gaut_run", false)\n            updateStatus()\n            return\n        end\n\n        local list = scanMachines()\n        if #list == 0 then\n            S.running = false\n            S.state = "Stopped"\n            notify("No Gaia\'s Beacon or Unstable Tesseract found in this world.")\n            pcall(editToggle, "zs_gaut_run", false)\n            updateStatus()\n            return\n        end\n\n        local didWork = false\n        S.state = "Running"\n        updateStatus()\n\n        for _, m in ipairs(list) do\n            if not alive(token) then break end\n            local r = processMachine(m, token)\n            if r == "worked" then didWork = true end\n            if stopFlag then break end\n        end\n\n        if stopFlag then\n            local msg = stopFlag\n            stopFlag = nil\n            S.running = false\n            S.state = "Stopped"\n            notify(msg)\n            pcall(editToggle, "zs_gaut_run", false)\n            updateStatus()\n            return\n        end\n\n        if alive(token) and not didWork then\n            S.state = "Idle (all empty)"\n            S.machine = "-"\n            updateStatus()\n            wait(CFG.idleWait, token)\n        end\n    end\nend\n\nlocal function stop(reason)\n    if reason then notify(reason) end\n    S.running = false\n    S.waiting = false\n    S.token = S.token + 1\n    S.state = "Stopped"\n    S.machine = "-"\n    pcall(editToggle, "zs_gaut_run", false)\n    updateStatus()\nend\n\nlocal function start()\n    if S.running then return end\n    if not S.dropX then\n        notify("Set the drop position first.")\n        pcall(editToggle, "zs_gaut_run", false)\n        return\n    end\n    if type(GetWorldName) ~= "function" or GetWorldName() ~= S.dropWorld then\n        notify("Drop position belongs to another world - set it again.")\n        pcall(editToggle, "zs_gaut_run", false)\n        return\n    end\n\n    S.running = true\n    S.token = S.token + 1\n    S.state = "Running"\n    local token = S.token\n    updateStatus()\n    notify("Started - Gaia + Unstable Tesseract")\n    runThread(function() mainLoop(token) end)\nend\n\n-- -------------------------------------------------------------------------\n--  Hooks\n-- -------------------------------------------------------------------------\n\n-- Reads the machine dialog and hides the machine / drop dialogs while running\nlocal function onVariant(var, pkt)\n    -- PowerKuy can dispatch an empty/nil variant during world transitions.\n    -- Ignore it instead of indexing a missing local-player/variant table.\n    if type(var) ~= "table" then return false end\n    if type(var.v1) ~= "string" or var.v1 ~= "OnDialogRequest" then return false end\n    if not S.running then return end\n\n    local text = tostring(var.v2 or "")\n\n    if S.waiting then\n        local info = parseMachineDialog(text)\n        if info then\n            S.info = info\n            return true\n        end\n    end\n\n    -- hide the "how many to remove" box, the machine box and the drop box\n    if text:find("end_dialog|itemremovedfromsucker|")\n        or text:find("end_dialog|drop_item|")\n        or text:find(MACHINES.gaia.dialog, 1, true)\n        or text:find(MACHINES.ut.dialog, 1, true) then\n        return true\n    end\nend\n\naddHook(function(type, name, value)\n    if name == "zs_gaut_run" then\n        if value then start() else\n            if S.running then stop("Stopped") end\n        end\n\n    elseif name == "zs_gaut_gaia" then\n        if value then\n            if S.kind ~= "gaia" then\n                S.kind = "gaia"\n                saved:set("kind", S.kind); saved:save()\n                pcall(editToggle, "zs_gaut_ut", false)\n                updateStatus()\n            end\n        elseif S.kind == "gaia" then\n            pcall(editToggle, "zs_gaut_gaia", true)   -- keep one source selected\n        end\n\n    elseif name == "zs_gaut_ut" then\n        if value then\n            if S.kind ~= "ut" then\n                S.kind = "ut"\n                saved:set("kind", S.kind); saved:save()\n                pcall(editToggle, "zs_gaut_gaia", false)\n                updateStatus()\n            end\n        elseif S.kind == "ut" then\n            pcall(editToggle, "zs_gaut_ut", true)\n        end\n\n    elseif name == "zs_gaut_setdrop" then\n        local x, y = myTile()\n        S.dropX, S.dropY, S.dropWorld = x, y, GetWorldName()\n        saved:set("drop_x", x); saved:set("drop_y", y); saved:set("drop_world", S.dropWorld)\n        saved:save()\n        notify("Drop position set: " .. x .. ", " .. y)\n        updateStatus()\n\n    elseif name == "zs_gaut_delay" then\n        S.delay = math.floor(tonumber(value) or 120)\n        saved:set("delay", S.delay); saved:save()\n    end\nend, "onValue")\n\n-- -------------------------------------------------------------------------\n--  UI module\n-- -------------------------------------------------------------------------\nlocal ui = UserInterface.new("ZS AUTO GAUT", "Shield")\nui:addLabelApp("* ZS AUTO GAUT *", "Shield")\nui:addTooltip("* ZS AUTO GAUT *", "Automatically retrieves items from Gaia\'s Beacon and Unstable Tesseract, then drops them at your saved position. Select a source and set the drop position before starting.", "Info", true)\nui:addDivider()\nui:addToggle("ZS AUTO GAUT", false, "zs_gaut_run", true)\nui:addDivider()\nui:addLabel("Source")\nui:addToggle("Gaia\'s Beacon", S.kind == "gaia", "zs_gaut_gaia", false)\nui:addToggle("Unstable Tesseract", S.kind == "ut", "zs_gaut_ut", false)\nui:addDivider()\nui:addButton("Set Drop Position", "zs_gaut_setdrop")\nui:addSlider("Packet Delay (ms)", 0, 500, S.delay, 10, false, "zs_gaut_delay")\nui:addDivider()\nui:addDisplayList("Status", "Default", "zs_gaut_status")\n\naddIntoModule(ui:generateJSON(), "ZS")\nupdateStatus()\naddHook(onVariant, "onVariant")\nsay("Loaded - Script Created By " .. CFG.author)\n'
  v("ZS_Auto_Science", Y)
  v("ZS_Multiworld_Provider_V2", K)
