  local c = "Commands of another proxy. Not part of ZS."
  local d =
    '-- ==========================================================\n--                 ZS AUTO HARVEST\n--   Detects the planted tree/seed foreground above/at the player\'s position (not ground),\n--   then harvests only that same foreground ID in groups of 3.\n--   Multiworld list: comma/semicolon separated; blank=current.\n-- ==========================================================\nlocal hvRunning, hvStop = false, false\nlocal HV_WALK_DELAY = 250\nlocal function hvNote(msg)\n    if growtopia and type(growtopia.notify) == "function" then\n        pcall(growtopia.notify, tostring(msg))\n    else print("[ZS Auto Harvest] " .. tostring(msg)) end\nend\nlocal function hvPlayer()\n    if type(GetLocal) ~= "function" then return nil end\n    local ok, p = pcall(GetLocal); if ok then return p end\nend\nlocal function hvTile(x,y)\n    if type(GetTile) ~= "function" then return nil end\n    local ok,t = pcall(GetTile,x,y); if ok then return t end\nend\nlocal function hvFg(t) return tonumber(t and t.fg) or 0 end\nlocal function hvDetectSeedUnderPlayer()\n    local p = hvPlayer()\n    if not p then return nil end\n    local px = math.floor((tonumber(p.posX) or 0) / 32)\n    local py = math.floor((tonumber(p.posY) or 0) / 32)\n\n    -- GetLocal.posY is the player\'s body position; the tile below the\n    -- feet is commonly ordinary dirt (FG 2), not the planted tree.\n    -- Check the occupied/upper tiles first and never accept base dirt.\n    local candidates = {\n        {px, py - 1}, {px, py}, {px - 1, py - 1},\n        {px + 1, py - 1}, {px - 1, py}, {px + 1, py},\n        {px, py - 2}\n    }\n    for _, pos in ipairs(candidates) do\n        local tile = hvTile(pos[1], pos[2])\n        local fg = hvFg(tile)\n        if fg > 0 and fg ~= 2 then\n            return fg, pos[1], pos[2]\n        end\n    end\n    return nil\nend\nlocal function hvGroups(blockID)\n    local list = {}\n    if type(GetTiles) ~= "function" then return list end\n    local ok, tiles = pcall(GetTiles)\n    if not ok or type(tiles) ~= "table" then return list end\n    for _,t in pairs(tiles) do\n        local x,y = tonumber(t.x),tonumber(t.y)\n        if x and y and hvFg(t) == blockID then\n            list[#list+1] = {x=math.floor(x),y=math.floor(y)}\n        end\n    end\n    table.sort(list,function(a,b) if a.y==b.y then return a.x<b.x end return a.y<b.y end)\n    local groups,i={},1\n    while i<=#list do\n        local first=list[i]; local g={first}; local j=i+1\n        -- Hard cap: one pass contains at most 3 trees, then the bot\n        -- walks to the next group before punching again.\n        while j<=#list and #g<3 and list[j].y==first.y\n          and list[j].x<=first.x+2 do\n            g[#g+1]=list[j]; j=j+1\n        end\n        groups[#groups+1]=g; i=j\n    end\n    return groups\nend\nlocal function hvNear(x,y)\n    local p=hvPlayer(); if not p then return false end\n    return math.abs((p.posX or 0)/32-x)<=2 and math.abs((p.posY or 0)/32-y)<=2\nend\nlocal function hvPunch(x,y)\n    local p=hvPlayer()\n    if not p or type(SendPacketRaw)~="function" then return false end\n    -- PowerKuy punch packets use tile coordinates for px/py (same as\n    -- the working Harvest Provider punch helper in this script).\n    local ok=pcall(SendPacketRaw,false,{x=p.posX,y=p.posY,px=x,py=y,type=3,value=18})\n    return ok\nend\nlocal function hvHarvestWorld(blockID,delay)\n    local total=0\n    local function rowTrees(rowY)\n        local list={}\n        if type(GetTiles)~="function" then return list end\n        local ok,tiles=pcall(GetTiles)\n        if not ok or type(tiles)~="table" then return list end\n        for _,t in pairs(tiles) do\n            local x,y=tonumber(t.x),tonumber(t.y)\n            if x and y and math.floor(y)==rowY and hvFg(t)==blockID then\n                list[#list+1]={x=math.floor(x),y=rowY}\n            end\n        end\n        table.sort(list,function(a,b) return a.x<b.x end)\n        return list\n    end\n\n    -- Process one complete horizontal row before moving to the next row.\n    while not hvStop do\n        local groups=hvGroups(blockID)\n        if #groups==0 then return total,"done" end\n\n        local rows,seen={},{}\n        for _,g in ipairs(groups) do\n            for _,t in ipairs(g) do\n                if not seen[t.y] then\n                    seen[t.y]=true\n                    rows[#rows+1]=t.y\n                end\n            end\n        end\n        table.sort(rows)\n\n        local didWork=false\n        for _,rowY in ipairs(rows) do\n            if hvStop then return total,"stop" end\n\n            -- Keep revisiting this same row until a fresh tile scan confirms\n            -- that no matching tree remains on it.\n            local stalledPasses=0\n            while not hvStop do\n                local remaining=rowTrees(rowY)\n                if #remaining==0 then break end\n\n                -- Walk to the end of the row, then harvest left-to-right.\n                local last=remaining[#remaining]\n                if type(FindPath)=="function" then\n                    pcall(FindPath,last.x+1,last.y)\n                end\n                Sleep(HV_WALK_DELAY)\n\n                for _,tree in ipairs(remaining) do\n                    if hvStop then return total,"stop" end\n                    if hvFg(hvTile(tree.x,tree.y))==blockID then\n                        if not hvNear(tree.x,tree.y) then\n                            if type(FindPath)=="function" then\n                                pcall(FindPath,tree.x+1,tree.y)\n                            end\n                            Sleep(HV_WALK_DELAY)\n                        end\n                        if hvNear(tree.x,tree.y) then\n                            if not hvPunch(tree.x,tree.y) then return total,"packet" end\n                            Sleep(delay)\n                            if hvFg(hvTile(tree.x,tree.y))~=blockID then\n                                total=total+1\n                                didWork=true\n                            end\n                        end\n                    end\n                end\n\n                -- End-of-row verification: if trees remain, return to them\n                -- on the next pass instead of advancing to another row.\n                local after=rowTrees(rowY)\n                if #after==0 then break end\n                local madeProgress=false\n                for _,tree in ipairs(remaining) do\n                    if hvFg(hvTile(tree.x,tree.y))~=blockID then\n                        madeProgress=true\n                        break\n                    end\n                end\n                if madeProgress then\n                    stalledPasses=0\n                else\n                    stalledPasses=stalledPasses+1\n                end\n                if stalledPasses>=3 then\n                    return total,"blocked"\n                end\n                -- Explicitly go back toward the first remaining tree.\n                if type(FindPath)=="function" then\n                    pcall(FindPath,after[1].x+1,after[1].y)\n                end\n                Sleep(HV_WALK_DELAY)\n            end\n        end\n\n        if not didWork then\n            -- Do not silently skip a row if the game/API is not updating tiles.\n            return total,"blocked"\n        end\n        Sleep(150)\n    end\n    return total,"stop"\nend\nlocal function hvParseWorlds(raw)\n    local out,seen={},{}\n    raw=tostring(raw or "")\n    for entry in raw:gmatch("[^,;\\\\n]+") do\n        entry=entry:match("^%s*(.-)%s*$")\n        if entry~="" then\n            local world,door = entry:match("^([^:|]+)[:|](%d+)$")\n            if not world then world=entry end\n            world=world:match("^%s*(.-)%s*$")\n            door=door and tostring(tonumber(door)) or nil\n            local key=world:upper().."|"..tostring(door or "")\n            if world~="" and not seen[key] then\n                seen[key]=true\n                out[#out+1]={name=world,door=door}\n            end\n        end\n    end\n    if #out==0 and type(GetWorldName)=="function" then\n        local w=GetWorldName()\n        if w and w~="EXIT" then out[1]={name=w} end\n    end\n    return out\nend\nlocal function hvWarpWorld(worldEntry)\n    local world=worldEntry.name\n    local door=worldEntry.door\n    if door then\n        SendPacket(3,"action|join_request\\\\nname|"..world.."\\\\ninvitedWorld|0\\\\ndoorID|"..door)\n    else\n        growtopia.warpTo(world)\n    end\n    local waited=0\n    while waited<15000 and not hvStop do\n        if type(GetWorldName)=="function" and GetWorldName():upper()==world:upper() then break end\n        Sleep(250); waited=waited+250\n    end\n    if type(GetWorldName)~="function" or GetWorldName():upper()~=world:upper() then return false end\n    Sleep(600)\n    return true\nend\nlocal function hvRun()\n    hvStop=false\n    local target, seedX, seedY = hvDetectSeedUnderPlayer()\n    if not target or target <= 0 then\n        hvNote("Stand directly on or next to the seed you want to harvest, then turn Auto Harvest ON.")\n        hvRunning=false\n        return\n    end\n    local delay=tonumber(getValue(2,"zs_hv_delay")) or 200\n    delay=math.max(80,math.min(1500,math.floor(delay)))\n    local worlds=hvParseWorlds(getValue(2,"zs_hv_worlds"))\n    if not growtopia or type(growtopia.warpTo)~="function" then hvNote("World warp API unavailable."); hvRunning=false; return end\n    hvNote("Detected seed/tree ID "..target.." at "..seedX..","..seedY..". Only this exact tree type will be harvested in the listed worlds.")\n    local total=0\n    for _,worldEntry in ipairs(worlds) do\n        if hvStop then break end\n        local world=worldEntry.name\n        local current=type(GetWorldName)=="function" and GetWorldName() or ""\n        if current:upper()~=world:upper() or worldEntry.door then\n            if not hvWarpWorld(worldEntry) then hvNote("Could not enter world/door: "..world..(worldEntry.door and (":"..worldEntry.door) or "")); hvRunning=false; return end\n        end\n        local count,reason=hvHarvestWorld(target,delay); total=total+count\n        if reason=="blocked" or reason=="packet" then hvNote("Harvest stopped: "..reason..". Harvested "..total.." tiles."); hvRunning=false; return end\n    end\n    hvRunning=false\n    hvNote("Auto Harvest finished. Harvested "..total.." matching tiles.")\nend\nlocal hv=UserInterface.new("ZS AUTO HARVEST","Agriculture")\nhv:addLabelApp("* ZS AUTO HARVEST *","Agriculture")\nhv:addTooltip("* AUTO HARVEST *","Stand on or beside the seed you want to harvest, then switch Auto Harvest ON. The script detects its foreground ID automatically and harvests only that exact tree type in every listed world, in groups of 3. Enter worlds as WORLD or WORLD:DOOR_ID (example: FARM:5), separated by commas. Blank = current world.","Info",true)\nhv:addDivider()\nhv:addInputString("Worlds / Door IDs","","Worlds to Harvest","Example: WORLD1:5, WORLD2:12. The number after : is the door ID.","World:Door ID","zs_hv_worlds")\nhv:addSlider("Harvest Delay (ms)",80,1500,200,10,false,"zs_hv_delay")\nhv:addDivider()\nhv:addToggle("AUTO HARVEST",false,"zs_hv_run",true)\naddIntoModule(hv:generateJSON(),"ZS")\naddHook(function(evType,name,value)\n    if name=="zs_hv_run" then\n        if value then\n            if hvRunning then hvNote("Auto Harvest is already running."); return end\n            hvRunning=true; hvStop=false\n            ZS_thread(hvRun)\n        else\n            hvStop=true; hvNote("AUTO HARVEST: OFF.")\n        end\n    end\nend,"onValue")\n'
