  local A =
    '-- ==========================================================\n-- ZS VEND FINDER V2\n-- Searches item contents in both Vending Machine and DigiVend.\n-- Clicking a result pathfinds directly to that machine tile.\n-- ==========================================================\nlocal function zs_vend_find()\n    local found = {}\n    if type(GetTiles) ~= "function" then return found end\n    local ok, tiles = pcall(GetTiles)\n    if not ok or type(tiles) ~= "table" then return found end\n    for _, tile in pairs(tiles) do\n        if tile and (tile.fg == 2978 or tile.fg == 9268) then\n            local ex = tile.extra\n            local itemID = ex and tonumber(ex.vend_item)\n            if ex and tonumber(ex.owner or 0) ~= 0 and itemID and itemID ~= 0 then\n                local info = type(getItemInfoByID) == "function" and getItemInfoByID(itemID) or nil\n                local itemName = info and info.name or ("Item ID " .. tostring(itemID))\n                found[#found + 1] = {\n                    x = tonumber(tile.x) or 0, y = tonumber(tile.y) or 0,\n                    id = itemID, name = itemName,\n                    price = tonumber(ex.vend_price) or 0\n                }\n            end\n        end\n    end\n    table.sort(found, function(a,b)\n        if a.name:lower() == b.name:lower() then\n            if a.y == b.y then return a.x < b.x end\n            return a.y < b.y\n        end\n        return a.name:lower() < b.name:lower()\n    end)\n    return found\nend\nlocal zs_vend_results_cache = {}\nlocal zs_vend_page = 1\nlocal zs_vend_search_query = ""\nlocal ZS_VEND_PAGE_SIZE = 18 -- 6 columns x 3 rows\n\nlocal function zs_vend_show_results(page, refresh)\n    if refresh or type(zs_vend_results_cache) ~= "table" then\n        zs_vend_results_cache = zs_vend_find()\n    end\n    local results = {}\n    local query = tostring(zs_vend_search_query or ""):lower():match("^%s*(.-)%s*$")\n    for _, item in ipairs(zs_vend_results_cache) do\n        if query == "" or tostring(item.name or ""):lower():find(query, 1, true) then\n            results[#results + 1] = item\n        end\n    end\n    local total = #results\n    local pages = math.max(1, math.ceil(total / ZS_VEND_PAGE_SIZE))\n    zs_vend_page = math.max(1, math.min(tonumber(page) or 1, pages))\n\n    local lines = {}\n    local first = (zs_vend_page - 1) * ZS_VEND_PAGE_SIZE + 1\n    local last = math.min(first + ZS_VEND_PAGE_SIZE - 1, total)\n\n    -- Use one compact clickable product button per result. Mixing full-width\n    -- textboxes and icon buttons made the dialog flow diagonally and detached\n    -- prices from their products. A single button keeps every label attached\n    -- to the correct product and lets Growtopia lay the buttons out left-to-right.\n    for i = first, last do\n        local r = results[i]\n        local price = math.abs(r.price)\n        local currencyID, priceText, currencyName\n        if r.price < 0 then\n            -- Negative vend_price means a quantity-for-1-WL offer (e.g. 2/1 WL).\n            -- Keep the slash for these deals; ordinary prices remain e.g. 16WL.\n            currencyID, priceText, currencyName = 242, tostring(price) .. "/1", "WL"\n        elseif price >= 10000 then\n            currencyID, priceText, currencyName = 7188, string.format("%.2f", price / 10000):gsub("%.?0+$", ""), "BGL"\n        elseif price >= 100 then\n            currencyID, priceText, currencyName = 1796, string.format("%.2f", price / 100):gsub("%.?0+$", ""), "DL"\n        else\n            currencyID, priceText, currencyName = 242, tostring(price), "WL"\n        end\n\n        local itemName = tostring(r.name or "Unknown item")\n        -- Compact labels are important: six product buttons must fit across one row.\n        if #itemName > 10 then itemName = itemName:sub(1, 8) .. ".." end\n        local buttonLabel = string.format("%s %s%s", itemName, priceText, currencyName)\n        lines[#lines + 1] = string.format(\n            "add_button_with_icon|%d-%d|%s|staticBlueFrame|%d||",\n            r.x, r.y, buttonLabel, r.id\n        )\n        -- Force a new dialog row after every six products: 6 left-to-right, 3 top-to-bottom.\n        if (i - first + 1) % 6 == 0 and i < last then\n            lines[#lines + 1] = "add_custom_break|"\n        end\n    end\n\n    local nav = {}\n    if total > 0 then\n        nav[#nav + 1] = string.format("add_textbox|`oShowing `w%d-%d`o of `w%d`o vending machines  -  Page `w%d/%d|left|", first, last, total, zs_vend_page, pages)\n        if pages > 1 then\n            nav[#nav + 1] = "add_button|zs_vend_prev|`w< PREVIOUS|noflags|"\n            nav[#nav + 1] = "add_button|zs_vend_next|`wNEXT >|noflags|"\n        end\n    end\n\n    local body = total > 0 and table.concat(lines, "\\n") or (query ~= "" and "add_textbox|`4No products match your search. Try another name.|left|" or "add_textbox|`4No vending items found in this world.``|")\n    growtopia.sendDialog(table.concat({\n        "set_default_color|`o",\n        "add_label_with_icon|big|`wZS VEND FINDER V2|left|2978|",\n        "add_text_input|zs_vend_search|Search product name:|" .. tostring(zs_vend_search_query):gsub("|", " "):gsub("\\n", " ") .. "|32|",\n        "add_button|zs_vend_apply_search|`2SEARCH|noflags|0|0|",\n        "add_button|zs_vend_clear_search|`9SHOW ALL|noflags|0|0|",\n        "add_textbox|`oTap a product tile to pathfind to its vending machine.|left|",\n        "add_spacer|small|",\n        body,\n        table.concat(nav, "\\n"),\n        "add_button|zs_vend_refresh|`wREFRESH LIST|noflags|",\n        "add_quick_exit|",\n        "end_dialog|zs_vend_results|Close||"\n    }, "\\n"))\n    if total == 0 and growtopia.notify then growtopia.notify("ZS Vend Finder: no vending items found.") end\nend\nlocal function zs_vend_path(x, y)\n    x, y = tonumber(x), tonumber(y)\n    if not x or not y then return end\n    local tile = type(getTile) == "function" and getTile(x, y) or nil\n    if not tile or (tile.fg ~= 2978 and tile.fg ~= 9268) then\n        if growtopia.notify then growtopia.notify("That vending machine is no longer there.") end\n        return\n    end\n    if growtopia.notify then growtopia.notify("Pathfinding to vending machine at " .. x .. "," .. y) end\n    if type(FindPath) == "function" then FindPath(x, y) end\nend\nlocal vend_ui = UserInterface.new("ZS VEND FINDER V2", "Search")\nvend_ui:addLabelApp("* ZS VEND FINDER V2 *", "Search")\nvend_ui:addTooltip("* VEND FINDER *", "Press the pink search button to list vending items in the current world. Search by product name to filter the list. Tap a product result to pathfind to that vending machine.", "Info", true)\nvend_ui:addDivider()\nvend_ui:addButton("SHOW VENDING ITEMS", "zs_vend_find_button")\naddIntoModule(vend_ui:generateJSON(), "ZS")\naddHook(function(vtype, name, value)\n    if name == "zs_vend_find_button" then\n        zs_vend_show_results(1, true)\n    end\nend, "onValue")\naddHook(function(ptype, packet)\n    if type(packet) ~= "string" then return false end\n    if packet:find("dialog_name|zs_vend_results", 1, true) then\n        local x, y = packet:match("buttonClicked|(%d+)%-(%d+)")\n        if x and y then\n            zs_vend_path(x, y)\n        elseif packet:find("buttonClicked|zs_vend_prev", 1, true) then\n            zs_vend_show_results(zs_vend_page - 1, false)\n        elseif packet:find("buttonClicked|zs_vend_next", 1, true) then\n            zs_vend_show_results(zs_vend_page + 1, false)\n        elseif packet:find("buttonClicked|zs_vend_apply_search", 1, true) then\n            zs_vend_search_query = packet:match("zs_vend_search|([^\\n|\\r]*)") or ""\n            zs_vend_show_results(1, false)\n        elseif packet:find("buttonClicked|zs_vend_clear_search", 1, true) then\n            zs_vend_search_query = ""\n            zs_vend_show_results(1, false)\n        elseif packet:find("buttonClicked|zs_vend_refresh", 1, true) then\n            zs_vend_show_results(1, true)\n        end\n        return true\n    end\n    return false\nend, "onsendpacket")\n\n'
  v("ZS_Vend_Finder_V2", A)
