unt and cooking device below.","type":"tooltip"},\n    {"type":"label","text":"COOKING SETTINGS"},\n    {"alias":"useoven","default":true,"text":"Use Oven","description":"Cook using standard ovens","type":"toggle"},\n    {"alias":"replicator","default":false,"text":"Use Replicator","description":"Cook using replicators","type":"toggle"},\n    {"type":"label","text":"SELECT FOOD"},\n    {"alias":"cook_4596","default":false,"text":"Berry Crepes","type":"toggle"},\n    {"alias":"cook_4604","default":false,"text":"Arroz Con Pollo","type":"toggle"},\n    {"alias":"cook_7056","default":false,"text":"Coconut Tart","type":"toggle"},\n    {"alias":"cook_5452","default":false,"text":"Gingerbread Cookie","type":"toggle"},\n    {"alias":"cook_6912","default":false,"text":"Skill Spice","type":"toggle"},\n    {"alias":"cook_4600","default":false,"text":"Beer-Battered Fish and Chips","type":"toggle"},\n    {"alias":"cook_10218","default":false,"text":"Trawlerman\'s Friend","type":"toggle"},\n    {"alias":"cook_1474","default":false,"text":"Eggs Benedict","type":"toggle"},\n    {"alias":"cook_6914","default":false,"text":"Gemonade","type":"toggle"},\n    {"alias":"cook_3240","default":false,"text":"Hot Chocolate","type":"toggle"},\n    {"type":"label","text":"ADDITIONAL SETTINGS"},\n    {"use_dot":true,"max":25,"text":"Number of Ovens","alias":"ovenvalue","step":1,"default":1,"type":"slider","min":1},\n    {"use_dot":true,"max":3000,"text":"Extra Delay (ms)","alias":"extrasleep","step":30,"default":-1000,"type":"slider","min":-3000},\n    {"alias":"recipes","text":"Show Selected Food Ingredients","type":"button"}\n  ],\n  "icon":"Fastfood"\n}\n]]\n\naddIntoModule(cookui, "ZS")\n\nlocal selected = 4596\nlocal running = false\nlocal loop = true\nlocal timer = 0\nlocal steps = 0\nlocal cooking_on = recipes[selected][1].cooking_on\nlocal ovenCount = getValue(1, "ovenvalue") or 6\nlocal extra_sleep = getValue(1, "extrasleep") \n\nfunction inv(itemID)\n    for _, obj in pairs(GetInventory()) do\n        if obj.id == itemID then return obj.amount end\n    end\n    return 0\nend\n\nfunction spr(type, value, tileX, tileY)\n    SendPacketRaw(false, {\n        type = type,\n        value = value,\n        px = tileX,\n        py = tileY,\n        x = GetLocal().posX,\n        y = GetLocal().posY\n    })\nend\n\nlocal function gp()\n    return { x = GetLocal().posX // 32, y = GetLocal().posY // 32 }\nend\n\nlocal function isOven(x, y)\n    local tile = GetTile(x, y)\n    if not tile then return false end\n    local fg = tile.fg\n    return (getValue(0, "useoven") and fg == 4618) or (getValue(0, "replicator") and fg == 6412)\nend\n\nfunction check_item(state)\n    state = state or false\n    local recipe = recipes[selected]\n    if not recipe then return false end\n\n    local ovenCount = tonumber(getValue(1, "ovenvalue")) or 1\n    local required = {}\n    local order = {}\n\n    -- Count each ingredient once per batch, including repeated ingredients.\n    for _, step in ipairs(recipe) do\n        if step.cook and step.cook ~= 18 then\n            local cookItems = type(step.cook) == "table" and step.cook or { step.cook }\n            for _, itemID in ipairs(cookItems) do\n                if not required[itemID] then\n                    required[itemID] = 0\n                    order[#order + 1] = itemID\n                end\n                required[itemID] = required[itemID] + 1\n            end\n        end\n    end\n\n    local items, hasMissing = {}, false\n    for _, itemID in ipairs(order) do\n        local perBatch = required[itemID]\n        local totalNeeded = perBatch * ovenCount\n        local count = inv(itemID)\n        local itemInfo = getItemInfoByID(itemID)\n        local itemName = itemInfo and itemInfo.name or ("Item ID " .. itemID)\n        local color = count < totalNeeded and "`4" or "`2"\n        if count < totalNeeded then hasMissing = true end\n        items[#items + 1] = "add_label_with_icon|small|`w" .. itemName ..\n          