turn hasMissing\nend\n\nfunction SendPackets(px, py, cookID, heatLevel)\n    if heatLevel == "medium" then heatLevel = "med" end\n    SendPacket(2,\n        "action|dialog_return\\n" ..\n        "dialog_name|oven\\n" ..\n        "tilex|" .. px .. "|\\n" ..\n        "tiley|" .. py .. "|\\n" ..\n        "cookthis|" .. cookID .. "|\\n" ..\n        "buttonClicked|" .. tostring(heatLevel or "low") .. "\\n\\n"\n    )\nend\n\nfunction processStep(step, index)\n    local ovenCount = getValue(1, "ovenvalue") or 1\n    local cookID = step.cook\n\n    local function stepprocess()\n        local ov = ovenCount\n\n        for yy = -2, 2 do\n            for xx = -2, 2 do\n                if not running then return end\n\n                local px = gp().x + xx\n                local py = gp().y + yy\n\n                if isOven(px, py) and ov > 0 then\n                    ov = ov - 1\n                    \n                    spr(3, cookID, px, py)\n                    SendPackets(px, py, cookID, cooking_on)\n\n                    CSleep(step.delay or 500)\n                end\n\n                CSleep(1)\n            end\n        end\n    end\n\n    if cookID == 18 then\n        stepprocess()\n    else\n        runCoroutine(function()\n            stepprocess()\n        end)\n    end\nend\n\nfunction letmecook()\n    while true do\n        if not running then\n            CSleep(500)\n        else\n            timer = 0\n            steps = 0\n\n            if check_item() then\n                running = false\n                CSleep(500)\n            end\n\n            local recipe = recipes[selected]\n\n            if recipe and running then\n                for i, step in ipairs(recipe) do\n                    if not running then break end\n                    steps = i\n                    processStep(step, i)\n\n                    if step.sleep then\n                        local target = step.sleep\n                        local nextStep = recipe[i + 1]\n\n                        if i == #recipe or (nextStep and nextStep.cook == 18) then\n                            target = target + (extra_sleep or 0)\n                        end\n\n                        local passed = 0\n                        while passed < target do\n                            if not running then break end\n                            local tick = math.min(1000, target - passed)\n                            CSleep(tick)\n                            passed = passed + tick\n                        end\n                    end\n                end\n            end\n\n            if running then\n                running = false\n                timer = 0\n                steps = 0\n                editValue("cook_" .. tostring(selected), false)\n                growtopia.notify("Auto Cook batch complete: " .. tostring(selected))\n            end\n        end\n    end\nend\n\nrunCoroutine(letmecook)\n\nrunCoroutine(function()\n    while true do\n        if running then timer = timer + 1 end\n        CSleep(1000)\n    end\nend)\n\naddHook(function(vtype, name, value)\n    if name == "recipes" then\n        check_item(true)\n    elseif name == "extrasleep" then\n        extra_sleep = tonumber(value) or getValue(1, "extrasleep") or 0\n    elseif type(name) == "string" and name:match("^cook_%d+$") then\n        local recipeID = tonumber(name:match("^cook_(%d+)$"))\n        if value then\n            if not recipeID or not recipes[recipeID] then\n                growtopia.notify("This food is not available in the cooking database.")\n                editValue(name, false)\n                return\n            end\n            if selected ~= recipeID then\n                local previousAlias = "cook_" .. tostring(selected)\n                if recipes[selected] then editValue(previousAlias, false) end\n            end\n            selected = recipeID\n            cooking_on = recipes[selected][1].cooking_on or "low"\n            if check_item() then\n                running = false\n                editValue(name, false)\n                growtopia.notify("Missing ingredients. Add the required items before starting.")\n                return\n            end\n            running = true\n            local selectedInfo = getItemInfoByID(selected)\n            growtopia.notify("Auto Cook started: " .. (selectedInfo and selectedInfo.name or tostring(selected)))\n        elseif selected == recipeID then\n            running = false\n            timer = 0\n            steps = 0\n        end\n    end\nend, "onValue")\n\n\n\ngrowtopia.notify("ZS Auto Cook V1 loaded. Open the ZS menu to configure recipes.")\n'
