"\\\\r"):gsub("\\t", "\\\\t")\n    return \'"\' .. s .. \'"\'\nend\n\nlocal function encodeJsonValue(v)\n    local tv = type(v)\n    if tv == "nil" then return "null"\n    elseif tv == "boolean" then return v and "true" or "false"\n    elseif tv == "number" then return tostring(v)\n    elseif tv == "string" then return escapeJsonStr(v)\n    elseif tv == "table" then\n        local isArr = true\n        local maxIdx = 0\n        for k, _ in pairs(v) do\n            if type(k) ~= "number" or k < 1 or math.floor(k) ~= k then\n                isArr = false\n                break\n            end\n            if k > maxIdx then maxIdx = k end\n        end\n        if isArr then\n            local parts = {}\n            for i = 1, maxIdx do\n                table.insert(parts, encodeJsonValue(v[i]))\n            end\n            return "[" .. table.concat(parts, ",") .. "]"\n        else\n            local parts = {}\n            for k, val in pairs(v) do\n                table.insert(parts, escapeJsonStr(k) .. ":" .. encodeJsonValue(val))\n            end\n            return "{" .. table.concat(parts, ",") .. "}"\n        end\n    end\n    return "null"\nend\n\n-- ============================================================================\n-- 2. EMBEDDED DEBUG PACK DATABASE (SESUAI debugpack & RUNTIME STATE\n-- ============================================================================\nlocal EMBEDDED_DEBUG_PACKS = [=[\nUpgrade Backpack:upgrade_backpack::\nClothes Pack:clothes_pack:50:234,210,1846,342,11202,214,138,354,2938,144,272,208,90,38,66,238,122,36,34,44,48,76,140,10034,694,142,236,270,130,40,68,42,374,372,3578,370\nRare Clothes Pack:rare_clothes:500:11204,600,1762,1028,1146,292,1708,5016,576,1736,348,1652,1650,294,3052,1330,890,1124,312,3530,1140,156,2882,258,452,9356,154,1478,1142,1120,150,2934,80,2928,1524,796,1126,152,1954,2576,2958,158,136,496,1848,896,1476,4954,1864,6674,296,290,310,1862,6796,4964,4968,2700,1316,1516,1854,1856,446,3590,1312,1688,1314,3466